    private ListenerConfig(final ListenerType type, final int port, final String host, KeyManager[] keyManagers, TrustManager[] trustManagers, HttpHandler rootHandler) {
        this.type = type;
        this.port = port;
        this.host = host;
        this.keyManagers = keyManagers;
