                .addHttpListener(0, HOST)
                .setHandler(textHandler("started"))
                .build());

        IllegalStateException beforeStart = assertThrows(IllegalStateException.class, server::getListenerInfo);
        assertNotNull(beforeStart.getMessage());
        assertTrue(beforeStart.getMessage().contains("Server not started"),
                "unexpected message: " + beforeStart.getMessage());

        server.start();

        assertNotNull(server.getXnio());
        assertNotNull(server.getWorker());
        assertEquals(1, server.getListenerInfo().size());

        server.stop();

        assertNull(server.getXnio());
        assertNull(server.getWorker());
        assertThrows(IllegalStateException.class, server::getListenerInfo);
    }

