    @Test
    void suspendClosesConnectionsAndResumeRestoresService() throws Exception {
        Undertow server = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(textHandler("suspendable"))
                .build());

        server.start();

        Undertow.ListenerInfo info = server.getListenerInfo().get(0);
        int port = portOf(info);
        assertFalse(info.isSuspended());

        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(HOST, port), 10_000);
            socket.setSoTimeout(10_000);
            writeRequest(socket, getRequest("/keepalive", false));
            HttpResponse first = readResponse(socket.getInputStream());
            assertEquals(200, first.status);
            assertEquals("suspendable", first.body);

            info.suspend();
            assertTrue(info.isSuspended());

            // suspending closes the connections that the listener is keeping alive
            int read;
            try {
                read = socket.getInputStream().read();
            } catch (SocketException e) {
                read = -1;
            }
            assertEquals(-1, read, "the connection must be closed once the listener is suspended");
        }

        info.resume();
        assertFalse(info.isSuspended());

        HttpResponse afterResume = get(port, "/resumed");
        assertEquals(200, afterResume.status);
        assertEquals("suspendable", afterResume.body);
    }

