    @Test
    void stopClosesTheListenersAndShutsDownTheInternalWorker() throws Exception {
        Undertow server = track(Undertow.builder()
                .addHttpListener(0, HOST)
                .setHandler(textHandler("stoppable"))
                .setServerOption(UndertowOptions.SHUTDOWN_TIMEOUT, Integer.valueOf(10_000))
                .build());

        server.start();

        int port = portOf(server.getListenerInfo().get(0));
        XnioWorker worker = server.getWorker();
        assertNotNull(worker);
        assertFalse(worker.isShutdown());
        assertEquals(200, get(port, "/before-stop").status);

        server.stop();

        assertTrue(worker.isShutdown(), "the worker created by start() must be shut down by stop()");
        assertNull(server.getWorker());
        assertNull(server.getXnio());
        assertThrows(IllegalStateException.class, server::getListenerInfo);
        assertThrows(IOException.class, () -> get(port, "/after-stop"));

        // stop() is idempotent
        server.stop();
    }

    @Test
    void externallySuppliedWorkerIsReusedAndSurvivesStop() throws Exception {
        Xnio xnio = Xnio.getInstance(UndertowTests.class.getClassLoader());
        XnioWorker worker = xnio.createWorker(OptionMap.create(Options.WORKER_IO_THREADS, Integer.valueOf(1)));
        assertNotNull(worker);
        try {
            Undertow first = track(Undertow.builder()
                    .setWorker(worker)
                    .addHttpListener(0, HOST)
                    .setHandler(textHandler("shared-worker"))
                    .build());

            assertSame(worker, first.getWorker(), "the builder worker is exposed before start");

            first.start();
            assertSame(worker, first.getWorker());
            assertEquals(200, get(portOf(first.getListenerInfo().get(0)), "/first").status);

            first.stop();

            assertFalse(worker.isShutdown(), "an externally supplied worker must not be shut down by stop()");
            assertFalse(worker.awaitTermination(50, TimeUnit.MILLISECONDS));
            assertSame(worker, first.getWorker());

            // the worker is still usable for a new server instance
            Undertow second = track(Undertow.builder()
                    .setWorker(worker)
                    .addHttpListener(0, HOST)
                    .setHandler(textHandler("second-server"))
                    .build());
            second.start();
            HttpResponse response = get(portOf(second.getListenerInfo().get(0)), "/second");
            assertEquals(200, response.status);
            assertEquals("second-server", response.body);
            second.stop();

            assertFalse(worker.isShutdown());
        } finally {
            worker.shutdown();
            worker.awaitTermination();
        }
    }

    @Test
    void failedStartShutsDownTheInternalWorkerAndThrows() throws Exception {
        try (ServerSocket blocker = new ServerSocket(0, 1, java.net.InetAddress.getByName(HOST))) {
            int port = blocker.getLocalPort();

            Undertow server = track(Undertow.builder()
                    .addHttpListener(port, HOST)
                    .setHandler(textHandler("never-served"))
                    .build());

            RuntimeException failure = assertThrows(RuntimeException.class, server::start);
            assertNotNull(findCause(failure, BindException.class),
                    "expected a BindException in the cause chain of " + failure);

            XnioWorker worker = server.getWorker();
            assertNotNull(worker);
            assertTrue(worker.isShutdown(), "the worker must be shut down when start() fails");
            assertThrows(IllegalStateException.class, server::getListenerInfo);
        }
    }

