@Timeout(90)
class UndertowTests {

    private static final String HOST = "127.0.0.1";
    private static final String KEYSTORE_PASSWORD = "password";

    /** Two HTTP/2 settings frames, base64url encoded (RFC 7540 section 3.2.1 example payload). */
