        assertEquals(200, response.status);
        assertEquals("keymanagers", response.body);
    }

    @Test
    void httpsListenerWithHttp2EnabledStillFallsBackToHttp11() throws Exception {
        SSLContext sslContext = serverSslContext();
        Undertow server = track(Undertow.builder()
                .addListener(new Undertow.ListenerBuilder()
                        .setType(Undertow.ListenerType.HTTPS)
                        .setHost(HOST)
                        .setPort(0)
                        .setSslContext(sslContext)
                        .setHttp2Enabled(true)
                        .setOverrideSocketOptions(OptionMap.create(Options.TCP_NODELAY, Boolean.TRUE)))
                .setHandler(textHandler("alpn"))
                .build());

