        assertTrue(worker.isShutdown(), "the worker created by start() must be shut down by stop()");
        assertNull(server.getWorker());
        assertNull(server.getXnio());
        assertThrows(IllegalStateException.class, server::getListenerInfo);
        assertThrows(IOException.class, () -> get(port, "/after-stop"));

        // stop() is idempotent
        server.stop();
    }

    @Test
