            Undertow second = track(Undertow.builder()
                    .setWorker(worker)
                    .addHttpListener(0, HOST)
                    .setHandler(textHandler("second-server"))
                    .build());
            second.start();
            HttpResponse response = get(portOf(second.getListenerInfo().get(0)), "/second");
            assertEquals(200, response.status);
            assertEquals("second-server", response.body);
