        int port = portOf(server.getListenerInfo().get(0));

        // plain requests are still served by the handler chain
        assertEquals("h2c-server-option", get(port, "/plain").body);

        HttpResponse upgrade = exchange(port, upgradeRequest("/upgrade"));
        assertEquals(101, upgrade.status);
