    @Test
    void proxyProtocolListenerRequiresAProxyHeader() throws Exception {
        Undertow server = track(Undertow.builder()
                .addListener(new Undertow.ListenerBuilder()
                        .setType(Undertow.ListenerType.HTTP)
                        .setHost(HOST)
                        .setPort(0)
                        .setUseProxyProtocol(true)
                        .setRootHandler(textHandler("proxied")))
                .setHandler(textHandler("ignored"))
                .build());

        server.start();

        int port = portOf(server.getListenerInfo().get(0));

        // a request without the PROXY preamble is rejected without an HTTP response
        byte[] rejected = exchangeAndReadAll(port,
                "GET / HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n");
        assertEquals(0, rejected.length,
                "connections without a proxy protocol header must be closed without a response");

        // with the PROXY preamble the request is handed to the configured handler
        String accepted = new String(exchangeAndReadAll(port,
                "PROXY TCP4 192.168.0.1 192.168.0.11 56324 80\r\n"
                        + "GET / HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n"),
                StandardCharsets.ISO_8859_1);
        assertTrue(accepted.startsWith("HTTP/1.1 200"), accepted);
        assertTrue(accepted.contains("proxied"), accepted);
    }

