    // ------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------

    private Undertow track(Undertow server) {
        servers.add(server);
        return server;
    }

    private static HttpHandler textHandler(String text) {
        return exchange -> respond(exchange, text);
    }

    private static void respond(HttpServerExchange exchange, String text) {
        byte[] bytes = text.getBytes(StandardCharsets.UTF_8);
        exchange.setStatusCode(200);
        exchange.getResponseHeaders().put(Headers.CONTENT_TYPE, "text/plain; charset=utf-8");
        exchange.getResponseHeaders().put(Headers.CONTENT_LENGTH, Integer.toString(bytes.length));
        exchange.getResponseSender().send(ByteBuffer.wrap(bytes));
    }

    private static int portOf(Undertow.ListenerInfo info) {
        SocketAddress address = info.getAddress();
        assertNotNull(address, "the listener info must expose the bound address");
        assertTrue(address instanceof InetSocketAddress, "unexpected address type " + address.getClass());
        return ((InetSocketAddress) address).getPort();
    }

    private static String getRequest(String path, boolean keepAlive) {
        return "GET " + path + " HTTP/1.1\r\n"
                + "Host: localhost\r\n"
                + (keepAlive ? "" : "Connection: close\r\n")
                + "\r\n";
    }

    private static String upgradeRequest(String path) {
        return "GET " + path + " HTTP/1.1\r\n"
                + "Host: localhost\r\n"
                + "Connection: Upgrade, HTTP2-Settings\r\n"
                + "Upgrade: h2c\r\n"
                + "HTTP2-Settings: " + HTTP2_SETTINGS + "\r\n"
                + "Connection: close\r\n"
                + "\r\n";
    }

    private static void writeRequest(Socket socket, String request) throws IOException {
        OutputStream out = socket.getOutputStream();
        out.write(request.getBytes(StandardCharsets.ISO_8859_1));
        out.flush();
    }

    private static HttpResponse exchange(int port, String rawRequest) throws IOException {
        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(HOST, port), 10_000);
            socket.setSoTimeout(10_000);
            writeRequest(socket, rawRequest);
            return readResponse(socket.getInputStream());
        }
    }

    private static HttpResponse get(int port, String path) throws IOException {
        return exchange(port, getRequest(path, false));
    }

    private static HttpResponse post(int port, String path, String body) throws IOException {
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(HOST, port), 10_000);
            socket.setSoTimeout(10_000);
            OutputStream out = socket.getOutputStream();
            out.write(("POST " + path + " HTTP/1.1\r\n"
                    + "Host: localhost\r\n"
                    + "Content-Type: text/plain\r\n"
                    + "Content-Length: " + bytes.length + "\r\n"
                    + "Connection: close\r\n"
                    + "\r\n").getBytes(StandardCharsets.ISO_8859_1));
            out.write(bytes);
            out.flush();
            return readResponse(socket.getInputStream());
        }
    }

    private static byte[] exchangeAndReadAll(int port, String rawRequest) throws IOException {
        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(HOST, port), 10_000);
            socket.setSoTimeout(10_000);
            writeRequest(socket, rawRequest);
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            byte[] buffer = new byte[1024];
            int read;
            while ((read = socket.getInputStream().read(buffer)) != -1) {
                out.write(buffer, 0, read);
            }
            return out.toByteArray();
        }
    }

    private static HttpResponse readResponse(InputStream in) throws IOException {
        String statusLine = readLine(in);
        if (statusLine == null) {
            throw new IOException("the connection was closed before a response was received");
        }
        Map<String, String> headers = new LinkedHashMap<>();
        String line;
        while ((line = readLine(in)) != null) {
            if (line.isEmpty()) {
                break;
            }
            int index = line.indexOf(':');
            if (index > 0) {
                headers.put(line.substring(0, index).trim().toLowerCase(Locale.ROOT),
                        line.substring(index + 1).trim());
            }
        }
        String[] statusParts = statusLine.split(" ");
        assertTrue(statusParts.length >= 2, "unexpected status line: " + statusLine);
        int status = Integer.parseInt(statusParts[1]);
        byte[] body = new byte[0];
        String contentLength = headers.get("content-length");
        if (contentLength != null) {
            body = in.readNBytes(Integer.parseInt(contentLength));
        }
        return new HttpResponse(statusLine, status, headers, body);
    }

    private static String readLine(InputStream in) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int read;
        while ((read = in.read()) != -1) {
            if (read == '\n') {
                byte[] bytes = out.toByteArray();
                int length = bytes.length;
                if (length > 0 && bytes[length - 1] == '\r') {
                    length--;
                }
                return new String(bytes, 0, length, StandardCharsets.ISO_8859_1);
            }
            out.write(read);
        }
        if (out.size() == 0) {
            return null;
        }
        return out.toString(StandardCharsets.ISO_8859_1);
    }

    private static Throwable findCause(Throwable throwable, Class<? extends Throwable> type) {
        Throwable current = throwable;
        while (current != null) {
            if (type.isInstance(current)) {
                return current;
            }
            current = current.getCause() == current ? null : current.getCause();
        }
        return null;
    }

    private static KeyManager[] keyManagers() throws Exception {
        KeyManagerFactory factory = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        factory.init(loadKeyStore(), KEYSTORE_PASSWORD.toCharArray());
        return factory.getKeyManagers();
    }

    private static TrustManager[] trustManagers() throws Exception {
        TrustManagerFactory factory = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        factory.init(loadKeyStore());
        return factory.getTrustManagers();
    }

    private static KeyStore loadKeyStore() throws Exception {
        KeyStore keyStore = KeyStore.getInstance("JKS");
        try (InputStream in = UndertowTests.class.getResourceAsStream("/server.keystore")) {
            assertNotNull(in, "the test keystore /server.keystore must be on the class path");
            keyStore.load(in, KEYSTORE_PASSWORD.toCharArray());
        }
        return keyStore;
    }

    private static SSLContext serverSslContext() throws Exception {
        SSLContext context = SSLContext.getInstance("TLS");
        context.init(keyManagers(), trustManagers(), new SecureRandom());
        return context;
    }

    private static SSLContext clientSslContext() throws Exception {
        SSLContext context = SSLContext.getInstance("TLS");
        context.init(null, new TrustManager[]{new X509TrustManager() {
            @Override
            public void checkClientTrusted(X509Certificate[] chain, String authType) {
            }

            @Override
            public void checkServerTrusted(X509Certificate[] chain, String authType) {
            }

            @Override
            public X509Certificate[] getAcceptedIssuers() {
                return new X509Certificate[0];
            }
        }}, new SecureRandom());
        return context;
    }

    private static HttpResponse getTls(int port, String path) throws Exception {
        try (SSLSocket socket = (SSLSocket) clientSslContext().getSocketFactory().createSocket()) {
            socket.connect(new InetSocketAddress(HOST, port), 10_000);
            socket.setSoTimeout(10_000);
            socket.startHandshake();
            writeRequest(socket, getRequest(path, false));
            return readResponse(socket.getInputStream());
        }
    }

    private static final class HttpResponse {

        private final String statusLine;
        private final int status;
        private final Map<String, String> headers;
        private final byte[] body;
        private final String body;

        private HttpResponse(String statusLine, int status, Map<String, String> headers, byte[] body) {
            this.statusLine = statusLine;
            this.status = status;
            this.headers = headers;
            this.body = body;
            this.body = new String(body, StandardCharsets.UTF_8);
        }

        private String header(String name) {
            return headers.get(name.toLowerCase(Locale.ROOT));
        }

        @Override
        public String toString() {
            return statusLine + " " + headers + " " + body;
        }
    }

    private static final class CountingByteBufferPool implements ByteBufferPool {

        private final ByteBufferPool delegate;
        private final AtomicInteger allocations = new AtomicInteger();

        private CountingByteBufferPool(ByteBufferPool delegate) {
            this.delegate = delegate;
        }

        @Override
        public PooledByteBuffer allocate() {
            allocations.incrementAndGet();
            return delegate.allocate();
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return delegate.getArrayBackedPool();
        }

        @Override
        public void close() {
            delegate.close();
        }

        @Override
        public int getBufferSize() {
            return delegate.getBufferSize();
        }

        @Override
        public boolean isDirect() {
            return delegate.isDirect();
        }
    }
