/**
 * Tests for {@link HttpClientConnection}. The connection is exercised against an in-memory
 * {@link StreamConnection} so that request bytes and response bytes can be observed deterministically.
 */
class HttpClientConnectionTests {

    private static XnioWorker worker;
    private static XnioIoThread ioThread;
    private static ByteBufferPool bufferPool;

    private final List<HttpClientConnection> openedConnections = new ArrayList<>();

    @BeforeAll
    static void createEnvironment() throws IOException {
        worker = Xnio.getInstance().createWorker(OptionMap.create(Options.THREAD_DAEMON, true));
        ioThread = worker.getIoThread();
        bufferPool = new DefaultByteBufferPool(false, 16 * 1024);
    }

    @AfterAll
    static void destroyEnvironment() {
        if (worker != null) {
            worker.shutdownNow();
        }
    }

    @AfterEach
    void closeConnections() {
        for (HttpClientConnection connection : openedConnections) {
            IoUtils.safeClose(connection);
        }
        openedConnections.clear();
    }

    // ---------------------------------------------------------------- basic accessors

    @Test
    void statisticsAreNotAvailableByDefault() {
        HttpClientConnection connection = newConnection();

        assertNull(connection.getStatistics());
        assertSame(bufferPool, connection.getBufferPool());
    }

    @Test
    void statisticsAreCollectedWhenEnabled() throws IOException {
        HttpClientConnection connection = newConnection(OptionMap.create(UndertowOptions.ENABLE_STATISTICS, true));

        ClientStatistics statistics = connection.getStatistics();
        assertNotNull(statistics);
        assertEquals(0L, statistics.getRequests());
        assertEquals(0L, statistics.getRead());
        assertEquals(0L, statistics.getWritten());

        RecordingCallback callback = send(connection, request(Methods.GET, "/statistics"));
        assertNull(callback.failure);
        assertEquals(1L, statistics.getRequests());
        assertTrue(statistics.getWritten() > 0L, "request head should be counted as written bytes");

        deliverResponse(connection, "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n");
        assertEquals(200, callback.exchange.getResponse().getResponseCode());
        assertTrue(statistics.getRead() > 0L, "response head should be counted as read bytes");

        statistics.reset();
        assertEquals(0L, statistics.getRequests());
        assertEquals(0L, statistics.getRead());
        assertEquals(0L, statistics.getWritten());
    }

    @Test
    void addressesWorkerAndIoThreadAreDelegated() {
        HttpClientConnection connection = newConnection();
        TestConnection transport = transport(connection);

        assertSame(transport.peerAddress, connection.getPeerAddress());
        assertSame(transport.peerAddress, connection.getPeerAddress(InetSocketAddress.class));
        assertNull(connection.getPeerAddress(UnrelatedAddress.class));
        assertSame(transport.localAddress, connection.getLocalAddress());
        assertSame(transport.localAddress, connection.getLocalAddress(InetSocketAddress.class));
        assertNull(connection.getLocalAddress(UnrelatedAddress.class));
        assertSame(worker, connection.getWorker());
        assertSame(ioThread, connection.getIoThread());
    }

    @Test
    void optionsAreDelegatedToTheUnderlyingConnection() throws IOException {
        HttpClientConnection connection = newConnection();
        Option<String> option = Option.simple(HttpClientConnectionTests.class, "TEST_OPTION", String.class);

        assertFalse(connection.supportsOption(option));
        assertNull(connection.getOption(option));

        assertNull(connection.setOption(option, "first"));
        assertTrue(connection.supportsOption(option));
        assertEquals("first", connection.getOption(option));
        assertEquals("first", connection.setOption(option, "second"));
        assertEquals("second", connection.getOption(option));
    }

    @Test
    void plainHttpConnectionCapabilities() {
        HttpClientConnection connection = newConnection();

        assertFalse(connection.isUpgraded());
        assertFalse(connection.isPushSupported());
        assertFalse(connection.isMultiplexingSupported());
        assertTrue(connection.isUpgradeSupported());
    }

    // ---------------------------------------------------------------- request writing

    @Test
    void sendRequestWritesRequestHeadAndFlushesEmptyBody() {
        HttpClientConnection connection = newConnection();
        ClientRequest request = request(Methods.GET, "/hello");
        request.getRequestHeaders().put(Headers.USER_AGENT, "test-agent");

        RecordingCallback callback = send(connection, request);

        assertNull(callback.failure);
        assertEquals(1, callback.completed);
        assertSame(request, callback.exchange.getRequest());
        String written = transport(connection).sinkText();
        assertTrue(written.startsWith("GET /hello HTTP/1.1\r\n"), written);
        assertTrue(written.contains("Host: localhost\r\n"), written);
        assertTrue(written.contains("User-Agent: test-agent\r\n"), written);
        assertTrue(written.endsWith("\r\n\r\n"), written);
        assertFalse(written.contains("Upgrade"), written);
        assertFalse(connection.isUpgraded());
        assertTrue(connection.isOpen());
    }

    @Test
    void sendRequestAddsHttp2UpgradeHeadersWhenHttp2IsEnabled() {
        HttpClientConnection connection = newConnection(OptionMap.create(UndertowOptions.ENABLE_HTTP2, true));
        ClientRequest request = request(Methods.GET, "/h2c");

        RecordingCallback callback = send(connection, request);

        assertNull(callback.failure);
        assertEquals("h2c", request.getRequestHeaders().getFirst(Headers.UPGRADE));
        assertEquals("Upgrade, HTTP2-Settings", request.getRequestHeaders().getFirst(Headers.CONNECTION));
        assertNotNull(request.getRequestHeaders().getFirst("HTTP2-Settings"));
        String written = transport(connection).sinkText();
        assertTrue(written.contains("Upgrade: h2c\r\n"), written);
        assertTrue(written.contains("HTTP2-Settings: "), written);
        // the upgrade header puts the connection into the upgrade-requested state
        assertTrue(connection.isUpgraded());

        RecordingCallback second = send(connection, request(Methods.GET, "/second"));
        assertEquals(1, second.failed);
        assertEquals(UndertowClientMessages.MESSAGES.invalidConnectionState().getMessage(), second.failure.getMessage());
        assertEquals(1, countOccurrences(transport(connection).sinkText(), "GET /"), "queued request must not be written");
    }

    @Test
    void sendRequestDoesNotAddUpgradeHeadersWhenHttp2IsDisabled() {
        HttpClientConnection connection = newConnection();
        ClientRequest request = request(Methods.GET, "/plain");

        RecordingCallback callback = send(connection, request);

        assertNull(callback.failure);
        assertFalse(request.getRequestHeaders().contains(Headers.UPGRADE));
        assertFalse(request.getRequestHeaders().contains("HTTP2-Settings"));
        assertFalse(connection.isUpgraded());

        RecordingCallback second = send(connection, request(Methods.GET, "/queued"));
        assertNull(second.failure);
        assertEquals(0, second.completed, "second request is queued while the first exchange is open");
        assertEquals(1, countOccurrences(transport(connection).sinkText(), "GET /"));
    }

    @Test
    void requestHeadIsDeferredUntilTheBodyIsWritten() throws IOException {
        HttpClientConnection connection = newConnection();
        ClientRequest request = request(Methods.POST, "/upload");
        request.getRequestHeaders().put(Headers.CONTENT_LENGTH, "5");

        RecordingCallback callback = send(connection, request);
        assertNull(callback.failure);
        assertEquals("", transport(connection).sinkText(), "head must not be flushed while a request body is expected");

        StreamSinkChannel requestChannel = callback.exchange.getRequestChannel();
        ByteBuffer body = ByteBuffer.wrap("hello".getBytes(StandardCharsets.US_ASCII));
        while (body.hasRemaining()) {
            requestChannel.write(body);
        }
        requestChannel.flush();

        String written = transport(connection).sinkText();
        assertTrue(written.startsWith("POST /upload HTTP/1.1\r\n"), written);
        assertTrue(written.contains("Content-Length: 5\r\n"), written);
        assertTrue(written.endsWith("\r\n\r\nhello"), written);
    }

    @Test
    void chunkedRequestBodyIsWrittenWithChunkFraming() throws IOException {
        HttpClientConnection connection = newConnection();
        ClientRequest request = request(Methods.POST, "/chunked");
        request.getRequestHeaders().put(Headers.TRANSFER_ENCODING, Headers.CHUNKED);

        RecordingCallback callback = send(connection, request);
        assertNull(callback.failure);

        StreamSinkChannel requestChannel = callback.exchange.getRequestChannel();
        ByteBuffer body = ByteBuffer.wrap("hello".getBytes(StandardCharsets.US_ASCII));
        while (body.hasRemaining()) {
            requestChannel.write(body);
        }
        requestChannel.shutdownWrites();

        String written = transport(connection).sinkText();
        assertTrue(written.startsWith("POST /chunked HTTP/1.1\r\n"), written);
        assertTrue(written.contains("5\r\nhello\r\n"), written);
        assertTrue(written.endsWith("0\r\n\r\n"), written);
    }

    @Test
    void invalidContentLengthFailsTheRequestAndClosesTheConnection() {
        HttpClientConnection connection = newConnection();
        CloseRecorder closeRecorder = new CloseRecorder();
        connection.addCloseListener(closeRecorder);
        ClientRequest request = request(Methods.POST, "/broken");
        request.getRequestHeaders().put(Headers.CONTENT_LENGTH, "not-a-number");

        RecordingCallback callback = send(connection, request);

        assertEquals(1, callback.failed);
        assertNull(callback.exchange);
        assertNotNull(callback.failure);
        assertTrue(callback.failure.getMessage().contains("not-a-number"), callback.failure.getMessage());
        assertEquals(1, closeRecorder.count);
        assertFalse(connection.isOpen());

        RecordingCallback afterClose = send(connection, request(Methods.GET, "/after"));
        assertEquals(1, afterClose.failed);
        assertInstanceOf(java.nio.channels.ClosedChannelException.class, afterClose.failure);
    }

