    // ---------------------------------------------------------------- queueing and completion

    @Test
    void queuedRequestStartsAfterTheFirstExchangeCompletes() throws IOException {
        HttpClientConnection connection = newConnection();
        RecordingCallback first = send(connection, request(Methods.GET, "/one"));
        RecordingCallback firstResponse = new RecordingCallback();
        first.exchange.setResponseListener(firstResponse);
        RecordingCallback second = send(connection, request(Methods.GET, "/two"));

        assertNull(second.failure);
        assertEquals(0, second.completed);
        assertEquals(1, countOccurrences(transport(connection).sinkText(), "GET /"));

        deliverResponse(connection, "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n");
        assertEquals(1, firstResponse.completed);
        assertEquals(0, second.completed, "second request is only started once the first response is drained");

        assertEquals("", readBody(firstResponse.exchange));
        assertEquals(1, second.completed, "second request should be initiated after exchange completion");
        String written = transport(connection).sinkText();
        assertEquals(1, countOccurrences(written, "GET /one HTTP/1.1"));
        assertEquals(1, countOccurrences(written, "GET /two HTTP/1.1"));
    }

    @Test
    void requestWithConnectionClosePreventsFurtherRequests() throws IOException {
        HttpClientConnection connection = newConnection();
        CloseRecorder closeRecorder = new CloseRecorder();
        connection.addCloseListener(closeRecorder);
        ClientRequest request = request(Methods.GET, "/last");
        request.getRequestHeaders().put(Headers.CONNECTION, Headers.CLOSE);

        RecordingCallback callback = send(connection, request);
        assertNull(callback.failure);
        assertFalse(connection.isOpen(), "a connection marked for closing is no longer reported as open");

        RecordingCallback rejected = send(connection, request(Methods.GET, "/rejected"));
        assertEquals(1, rejected.failed);
        assertEquals(UndertowClientMessages.MESSAGES.closedConnectionState().getMessage(), rejected.failure.getMessage());

        RecordingCallback response = new RecordingCallback();
        callback.exchange.setResponseListener(response);
        deliverResponse(connection, "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n");
        assertEquals(200, response.exchange.getResponse().getResponseCode());
        assertEquals("", readBody(response.exchange));
        assertEquals(1, closeRecorder.count, "connection is closed once the final exchange completes");
    }

