    @Test
    void performUpgradeExposesTheUnderlyingConnectionAndBlocksFurtherRequests() {
        HttpClientConnection connection = newConnection();
        RecordingCallback callback = send(connection, request(Methods.GET, "/upgrade"));
        assertNull(callback.failure);

        StreamConnection upgraded;
        try {
            upgraded = connection.performUpgrade();
        } catch (IOException e) {
            throw new AssertionError("upgrade should succeed", e);
        }

        assertSame(transport(connection), upgraded);
        assertTrue(connection.isUpgraded());
        assertSame(transport(connection).sink, transport(connection).getSinkChannel().getConduit());

        RecordingCallback rejected = send(connection, request(Methods.GET, "/after-upgrade"));
        assertEquals(1, rejected.failed);
        assertEquals(UndertowClientMessages.MESSAGES.invalidConnectionState().getMessage(), rejected.failure.getMessage());
    }

    // ---------------------------------------------------------------- close handling

    @Test
    void closeNotifiesListenersAndIsIdempotent() {
        HttpClientConnection connection = newConnection();
        CloseRecorder closeListener = new CloseRecorder();
        CloseRecorder connectionCloseSetter = new CloseRecorder();
        connection.addCloseListener(closeListener);
        connection.getCloseSetter().set(connectionCloseSetter);

        try {
            connection.close();
        } catch (IOException e) {
            throw new AssertionError("close should not fail", e);
        }

        assertEquals(1, closeListener.count);
        assertEquals(1, connectionCloseSetter.count);
        assertFalse(connection.isOpen());

        try {
            connection.close();
        } catch (IOException e) {
            throw new AssertionError("second close should not fail", e);
        }
        assertEquals(1, closeListener.count);
        assertEquals(1, connectionCloseSetter.count);

        RecordingCallback rejected = send(connection, request(Methods.GET, "/closed"));
        assertEquals(1, rejected.failed);
        assertInstanceOf(java.nio.channels.ClosedChannelException.class, rejected.failure);
    }

    @Test
    void underlyingConnectionCloseFailsCurrentAndPendingRequests() {
        HttpClientConnection connection = newConnection();
        ClientRequest blocking = request(Methods.POST, "/blocking");
        blocking.getRequestHeaders().put(Headers.CONTENT_LENGTH, "5");
        RecordingCallback current = send(connection, blocking);
        RecordingCallback currentResponse = new RecordingCallback();
        current.exchange.setResponseListener(currentResponse);
        RecordingCallback pending = send(connection, request(Methods.GET, "/pending"));
        assertEquals(0, pending.completed);

        try {
            transport(connection).close();
        } catch (IOException e) {
            throw new AssertionError("transport close should not fail", e);
        }

        assertEquals(1, currentResponse.failed);
        assertInstanceOf(java.nio.channels.ClosedChannelException.class, currentResponse.failure);
        assertEquals(1, pending.failed);
        assertInstanceOf(java.nio.channels.ClosedChannelException.class, pending.failure);
        assertFalse(connection.isOpen());
    }

