    @Test
    void fixedLengthResponseIsParsedAndBodyIsReadable() throws IOException {
        HttpClientConnection connection = newConnection();
        RecordingCallback callback = send(connection, request(Methods.GET, "/resource"));
        RecordingCallback response = new RecordingCallback();
        callback.exchange.setResponseListener(response);

        deliverResponse(connection, "HTTP/1.1 200 OK\r\nContent-Length: 5\r\nContent-Type: text/plain\r\n\r\nhello");

        assertEquals(1, response.completed);
        ClientExchange exchange = response.exchange;
        assertEquals(200, exchange.getResponse().getResponseCode());
        assertEquals("OK", exchange.getResponse().getReasonPhrase());
        assertEquals(Protocols.HTTP_1_1, exchange.getResponse().getProtocol());
        assertEquals("5", exchange.getResponse().getResponseHeaders().getFirst(Headers.CONTENT_LENGTH));
        assertEquals("text/plain", exchange.getResponse().getResponseHeaders().getFirst(Headers.CONTENT_TYPE));
        assertEquals("hello", readBody(exchange));
        assertTrue(connection.isOpen());

        RecordingCallback next = send(connection, request(Methods.GET, "/next"));
        assertNull(next.failure);
        assertEquals(1, countOccurrences(transport(connection).sinkText(), "GET /next HTTP/1.1"));
    }

