    @Test
    void responseWithConnectionCloseFailsQueuedRequests() throws IOException {
        HttpClientConnection connection = newConnection();
        CloseRecorder closeRecorder = new CloseRecorder();
        connection.addCloseListener(closeRecorder);
        ClientRequest blocking = request(Methods.POST, "/first");
        blocking.getRequestHeaders().put(Headers.CONTENT_LENGTH, "5");
        RecordingCallback first = send(connection, blocking);
        RecordingCallback firstResponse = new RecordingCallback();
        first.exchange.setResponseListener(firstResponse);
        RecordingCallback queued = send(connection, request(Methods.GET, "/queued"));

        deliverResponse(connection, "HTTP/1.1 200 OK\r\nConnection: close\r\nContent-Length: 0\r\n\r\n");

        assertEquals(1, firstResponse.completed);
        assertEquals(200, firstResponse.exchange.getResponse().getResponseCode());
        assertEquals(1, queued.failed);
        assertInstanceOf(IOException.class, queued.failure);
        assertFalse(connection.isOpen());
        assertEquals("", readBody(firstResponse.exchange));

        // finish the request side; the exchange should now complete and close the connection
        connection.requestFinishListener.handleEvent(null);
        assertEquals(1, closeRecorder.count);
    }

    @Test
    void continueResponseIsDeliveredBeforeTheFinalResponse() {
        HttpClientConnection connection = newConnection();
        ClientRequest request = request(Methods.POST, "/continue");
        request.getRequestHeaders().put(Headers.EXPECT, "100-continue");
        request.getRequestHeaders().put(Headers.CONTENT_LENGTH, "0");
        RecordingCallback callback = send(connection, request);
        int[] continuations = new int[1];
        callback.exchange.setContinueHandler(exchange -> continuations[0]++);

        transport(connection).source.add(
                "HTTP/1.1 100 Continue\r\n\r\nHTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n".getBytes(StandardCharsets.ISO_8859_1));
        invokeReadListener(connection);

        assertEquals(1, continuations[0]);
        assertEquals(100, callback.exchange.getContinueResponse().getResponseCode());
        assertNull(callback.exchange.getResponse());

        invokeReadListener(connection);
        assertEquals(200, callback.exchange.getResponse().getResponseCode());
    }

    @Test
    void expectationFailedResponseClosesAConnectionThatRequestedContinue() throws IOException {
        HttpClientConnection connection = newConnection();
        ClientRequest request = request(Methods.POST, "/expect");
        request.getRequestHeaders().put(Headers.EXPECT, "100-continue");
        request.getRequestHeaders().put(Headers.CONTENT_LENGTH, "5");
        RecordingCallback callback = send(connection, request);
        RecordingCallback response = new RecordingCallback();
        callback.exchange.setResponseListener(response);

        deliverResponse(connection, "HTTP/1.1 417 Expectation Failed\r\nContent-Length: 0\r\n\r\n");

        assertEquals(1, response.completed);
        assertEquals(417, response.exchange.getResponse().getResponseCode());
        assertTrue(callback.exchange.isRequestDataSent(), "the request must be terminated after 417");
        assertFalse(connection.isOpen());
        assertEquals("", readBody(response.exchange));
    }

    @Test
    void successfulResponseWithoutUpgradeClearsTheUpgradeRequestState() throws IOException {
        HttpClientConnection connection = newConnection(OptionMap.create(UndertowOptions.ENABLE_HTTP2, true));
        RecordingCallback callback = send(connection, request(Methods.GET, "/h2c"));
        RecordingCallback response = new RecordingCallback();
        callback.exchange.setResponseListener(response);
        assertTrue(connection.isUpgraded());

        deliverResponse(connection, "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n");

        assertEquals(1, response.completed);
        assertFalse(connection.isUpgraded(), "a response without an Upgrade header abandons the upgrade");
        assertEquals("", readBody(response.exchange));

        RecordingCallback next = send(connection, request(Methods.GET, "/after"));
        assertNull(next.failure);
        assertEquals(1, next.completed);
    }

    @Test
    void requestAndResponseFinishListenersAreSafeWithoutAnActiveRequest() {
        HttpClientConnection connection = newConnection();

        // no current request: the listeners must simply do nothing
        connection.requestFinishListener.handleEvent(null);
        connection.responseFinishedListener.handleEvent(null);
        assertTrue(connection.isOpen());
    }

    // ---------------------------------------------------------------- helpers

    private HttpClientConnection newConnection() {
        return newConnection(OptionMap.create(UndertowOptions.ENABLE_HTTP2, false));
    }

    private HttpClientConnection newConnection(OptionMap options) {
        TestConnection transport = new TestConnection(ioThread);
        HttpClientConnection connection = new HttpClientConnection(transport, options, bufferPool);
        openedConnections.add(connection);
        return connection;
    }

    private static TestConnection transport(HttpClientConnection connection) {
        return (TestConnection) connection.getConnection();
    }

    private static ClientRequest request(io.undertow.util.HttpString method, String path) {
        ClientRequest request = new ClientRequest().setMethod(method).setPath(path).setProtocol(Protocols.HTTP_1_1);
        request.getRequestHeaders().put(Headers.HOST, "localhost");
        return request;
    }

    private static RecordingCallback send(HttpClientConnection connection, ClientRequest request) {
        RecordingCallback callback = new RecordingCallback();
        connection.sendRequest(request, callback);
        return callback;
    }

    private static void deliverResponse(HttpClientConnection connection, String rawResponse) {
        transport(connection).source.add(rawResponse.getBytes(StandardCharsets.ISO_8859_1));
        invokeReadListener(connection);
    }

    private static void invokeReadListener(HttpClientConnection connection) {
        ConduitStreamSourceChannel channel = connection.getConnection().getSourceChannel();
        ChannelListener<? super ConduitStreamSourceChannel> listener = channel.getReadListener();
        assertNotNull(listener, "the connection should have installed a read listener");
        listener.handleEvent(channel);
    }

    private static String readBody(ClientExchange exchange) throws IOException {
        StreamSourceChannel channel = exchange.getResponseChannel();
        ByteBuffer buffer = ByteBuffer.allocate(256);
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < 100; i++) {
            buffer.clear();
            int res = channel.read(buffer);
            if (res == -1) {
                return result.toString();
            }
            if (res == 0) {
                break;
            }
            buffer.flip();
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            result.append(new String(data, StandardCharsets.ISO_8859_1));
        }
        return result.toString();
    }

    private static int countOccurrences(String haystack, String needle) {
        int count = 0;
        int index = haystack.indexOf(needle);
        while (index != -1) {
            count++;
            index = haystack.indexOf(needle, index + needle.length());
        }
        return count;
    }

    private static final class RecordingCallback implements ClientCallback<ClientExchange> {
        ClientExchange exchange;
        IOException failure;
        int completed;
        int failed;

        @Override
        public void completed(ClientExchange result) {
            completed++;
            exchange = result;
        }

        @Override
        public void failed(IOException e) {
            failed++;
            failure = e;
        }
    }

    private static final class CloseRecorder implements ChannelListener<ClientConnection> {
        int count;

        @Override
        public void handleEvent(ClientConnection channel) {
            count++;
        }
    }

    private static final class UnrelatedAddress extends SocketAddress {
        private static final long serialVersionUID = 1L;
    }

    /**
     * A {@link StreamConnection} whose source and sink are backed by in-memory buffers.
     */
    private static final class TestConnection extends StreamConnection {

        private final SocketAddress peerAddress = new InetSocketAddress("127.0.0.1", 8080);
        private final SocketAddress localAddress = new InetSocketAddress("127.0.0.1", 43210);
        private final Map<Option<?>, Object> options = new HashMap<>();
        final TestSinkConduit sink;
        final TestSourceConduit source;

        TestConnection(XnioIoThread thread) {
            super(thread);
            sink = new TestSinkConduit(thread);
            source = new TestSourceConduit(thread);
            setSinkConduit(sink);
            setSourceConduit(source);
        }

        String sinkText() {
            return sink.text();
        }

        @Override
        public SocketAddress getPeerAddress() {
            return peerAddress;
        }

        @Override
        public SocketAddress getLocalAddress() {
            return localAddress;
        }

        @Override
        public boolean supportsOption(Option<?> option) {
            return options.containsKey(option);
        }

        @SuppressWarnings("unchecked")
        @Override
        public <T> T getOption(Option<T> option) throws IOException {
            return (T) options.get(option);
        }

        @SuppressWarnings("unchecked")
        @Override
        public <T> T setOption(Option<T> option, T value) throws IllegalArgumentException, IOException {
            return (T) options.put(option, value);
        }
    }

    /**
     * Sink conduit that records every byte written to the connection.
     */
    private static final class TestSinkConduit extends AbstractStreamSinkConduit<StreamSinkConduit> {

        private final ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        private boolean writesShutdown;

        TestSinkConduit(XnioIoThread thread) {
            super(new NullStreamSinkConduit(thread));
        }

        String text() {
            return new String(bytes.toByteArray(), StandardCharsets.ISO_8859_1);
        }

        @Override
        public int write(ByteBuffer src) {
            int count = src.remaining();
            byte[] data = new byte[count];
            src.get(data);
            bytes.write(data, 0, count);
            return count;
        }

        @Override
        public long write(ByteBuffer[] srcs, int offset, int length) {
            long total = 0;
            for (int i = offset; i < offset + length; i++) {
                total += write(srcs[i]);
            }
            return total;
        }

        @Override
        public boolean flush() {
            return true;
        }

        @Override
        public void terminateWrites() {
            writesShutdown = true;
        }

        @Override
        public boolean isWriteShutdown() {
            return writesShutdown;
        }
    }

    /**
     * Source conduit that serves test supplied bytes and optionally simulates EOF or an IO failure.
     */
    private static final class TestSourceConduit extends AbstractStreamSourceConduit<StreamSourceConduit> {

        private final Deque<ByteBuffer> buffers = new ArrayDeque<>();
        private boolean readsShutdown;
        boolean eof = true;
        IOException readException;

        TestSourceConduit(XnioIoThread thread) {
            super(new EmptyStreamSourceConduit(thread));
        }

        void add(byte[] data) {
            buffers.add(ByteBuffer.wrap(data));
        }

        @Override
        public int read(ByteBuffer dst) throws IOException {
            IOException toThrow = readException;
            if (toThrow != null) {
                readException = null;
                throw toThrow;
            }
            ByteBuffer current = buffers.peek();
            if (current == null) {
                return eof ? -1 : 0;
            }
            int count = Math.min(dst.remaining(), current.remaining());
            ByteBuffer source = current.duplicate();
            source.limit(source.position() + count);
            dst.put(source);
            current.position(current.position() + count);
            if (!current.hasRemaining()) {
                buffers.poll();
            }
            return count;
        }

        @Override
        public long read(ByteBuffer[] dsts, int offset, int length) throws IOException {
            if (length == 0) {
                return 0L;
            }
            long total = 0;
            for (int i = offset; i < offset + length; i++) {
                int res = read(dsts[i]);
                if (res == -1) {
                    return total == 0 ? -1 : total;
                }
                if (res == 0) {
                    break;
                }
                total += res;
            }
            return total;
        }

        @Override
        public long transferTo(long position, long count, FileChannel target) {
            throw new UnsupportedOperationException();
        }

        @Override
        public long transferTo(long count, ByteBuffer throughBuffer, StreamSinkChannel target) {
            throw new UnsupportedOperationException();
        }

        @Override
        public void terminateReads() {
            readsShutdown = true;
        }

        @Override
        public boolean isReadShutdown() {
            return readsShutdown;
        }
    }
}
