class HttpClientConnectionTests {

    private static XnioWorker worker;
    private static XnioIoThread ioThread;
    private static ByteBufferPool bufferPool;

    private final List<HttpClientConnection> openedConnections = new ArrayList<>();

    @BeforeAll
    static void createEnvironment() throws IOException {
        worker = Xnio.getInstance().createWorker(OptionMap.create(Options.THREAD_DAEMON, true));
        ioThread = worker.getIoThread();
        bufferPool = new DefaultByteBufferPool(false, 16 * 1024);
    }

    @AfterAll
    static void destroyEnvironment() {
        if (worker != null) {
            worker.shutdownNow();
