        assertEquals(0L, statistics.getRequests());
        assertEquals(0L, statistics.getRead());
        assertEquals(0L, statistics.getWritten());

        RecordingCallback callback = send(connection, request(Methods.GET, "/statistics"));
        assertNull(callback.failure);
        assertEquals(1L, statistics.getRequests());
        assertTrue(statistics.getWritten() > 0L, "request head should be counted as written bytes");

        deliverResponse(connection, "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n");
        assertEquals(200, callback.exchange.getResponse().getResponseCode());
        assertTrue(statistics.getRead() > 0L, "response head should be counted as read bytes");

        statistics.reset();
        assertEquals(0L, statistics.getRequests());
        assertEquals(0L, statistics.getRead());
        assertEquals(0L, statistics.getWritten());
    }

