        assertSame(transport.peerAddress, connection.getPeerAddress(InetSocketAddress.class));
        assertNull(connection.getPeerAddress(UnrelatedAddress.class));
        assertSame(transport.localAddress, connection.getLocalAddress());
        assertSame(transport.localAddress, connection.getLocalAddress(InetSocketAddress.class));
        assertNull(connection.getLocalAddress(UnrelatedAddress.class));
        assertSame(worker, connection.getWorker());
        assertSame(ioThread, connection.getIoThread());
