package io.undertow.protocols.http2;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import io.undertow.util.HeaderMap;
import io.undertow.util.Headers;
import io.undertow.util.HttpString;

/**
 * Behavioural tests for the HPACK encoder. The assertions use the HPACK wire
 * format and the companion decoder to verify the encoder's externally visible
 * contract.
 */
@Tag("io.undertow.testutils.category.UnitTest")
class HpackEncoderTests {

    private static final HttpString X_TEST = new HttpString("x-test");
    private static final HttpString X_ALPHA = new HttpString("x-alpha");
    private static final HttpString X_BETA = new HttpString("x-beta");

    private static final HpackEncoder.HpackHeaderFunction NO_INDEXING_OR_HUFFMAN = new HpackEncoder.HpackHeaderFunction() {
        @Override
        public boolean shouldUseIndexing(HttpString header, String value) {
            return false;
        }

        @Override
        public boolean shouldUseHuffman(HttpString header, String value) {
            return false;
        }

        @Override
        public boolean shouldUseHuffman(HttpString header) {
            return false;
        }
    };

    private static final HpackEncoder.HpackHeaderFunction ALWAYS_HUFFMAN = new HpackEncoder.HpackHeaderFunction() {
        @Override
        public boolean shouldUseIndexing(HttpString header, String value) {
            return true;
        }

        @Override
        public boolean shouldUseHuffman(HttpString header, String value) {
            return true;
        }

        @Override
        public boolean shouldUseHuffman(HttpString header) {
            return true;
        }
    };

    @Test
    void encodesExactStaticTableMatchesAsASingleIndexedOctet() {
        assertArrayEquals(octets(0x82), encodeFully(new HpackEncoder(4096), headers(":method", "GET")));
        assertArrayEquals(octets(0x84), encodeFully(new HpackEncoder(4096), headers(":path", "/")));
        assertArrayEquals(octets(0x87), encodeFully(new HpackEncoder(4096), headers(":scheme", "https")));
        assertArrayEquals(octets(0x88), encodeFully(new HpackEncoder(4096), headers(":status", "200")));
        assertArrayEquals(octets(0x8d), encodeFully(new HpackEncoder(4096), headers(":status", "404")));
        assertArrayEquals(octets(0x90), encodeFully(new HpackEncoder(4096), headers("accept-encoding", "gzip, deflate")));
    }

    @Test
    void encodesUnknownHeaderAsLiteralWithIncrementalIndexing() {
        byte[] encoded = encodeFully(new HpackEncoder(4096), headers("x-test", "abc"));

        assertArrayEquals(new byte[]{
                0x40, 0x06, 'x', '-', 't', 'e', 's', 't', 0x03, 'a', 'b', 'c'
        }, encoded);
    }

    @Test
    void usesStaticHeaderNameWithLiteralValue() {
        byte[] encoded = encodeFully(new HpackEncoder(4096), headers(":authority", "abc"));

        // 0x40 (literal with incremental indexing) + static index 1, then a
        // non-Huffman value because its length is below the default threshold.
        assertArrayEquals(new byte[]{0x41, 0x03, 'a', 'b', 'c'}, encoded);
    }

    @Test
    void indexesDynamicEntriesAndUsesTheirIndexOnTheNextEncoding() {
        HpackEncoder encoder = new HpackEncoder(4096);
        HeaderMap headers = headers("x-test", "abc");

        byte[] first = encodeFully(encoder, headers);
        assertEquals(0x40, first[0] & 0xff);

        // The first entry in the dynamic table has HPACK index 62.
        assertArrayEquals(octets(0xbe), encodeFully(encoder, headers));
    }

    @Test
    void preservesTheOrderOfMultipleValuesWhenUsingDynamicIndices() {
        HpackEncoder encoder = new HpackEncoder(4096);
        HeaderMap headers = headers("x-test", "abc", "def");

        encodeFully(encoder, headers);

        // The latest entry is index 62 and the first one is index 63.
        assertArrayEquals(new byte[]{(byte) 0xbf, (byte) 0xbe}, encodeFully(encoder, headers));
    }

    @Test
    void evictsTheOldestDynamicEntryWhenTheTableIsFull() throws Exception {
        HpackEncoder encoder = new HpackEncoder(80);
        encodeFully(encoder, headers("x-one", "aaa"));
        encodeFully(encoder, headers("x-two", "bbb"));
        encodeFully(encoder, headers("x-three", "ccc"));

        // x-one was evicted, while x-two is still present in the dynamic table.
        assertArrayEquals(octets(0xbf), encodeFully(encoder, headers("x-two", "bbb")));

        // Encoding x-one again therefore has to start with a literal field.
        assertArrayEquals(new byte[]{
                0x40, 0x05, 'x', '-', 'o', 'n', 'e', 0x03, 'a', 'a', 'a'
        }, encodeFully(encoder, headers("x-one", "aaa")));
    }

    @Test
    void emitsPseudoHeadersBeforeRegularHeaders() throws Exception {
        HeaderMap headers = new HeaderMap();
        headers.add(X_TEST, "abc");
        headers.add(new HttpString(":status"), "200");

        byte[] encoded = encodeFully(new HpackEncoder(4096), headers);

        assertArrayEquals(new byte[]{
                (byte) 0x88, 0x40, 0x06, 'x', '-', 't', 'e', 's', 't', 0x03, 'a', 'b', 'c'
        }, encoded);

        List<DecodedHeader> decoded = decode(encoded);
        assertEquals(2, decoded.size());
        assertEquals(":status", decoded.get(0).name.toString());
        assertEquals("x-test", decoded.get(1).name.toString());
    }

    @Test
    void dropsConnectionSpecificHeaders() throws Exception {
        HeaderMap headers = new HeaderMap();
        headers.add(Headers.CONNECTION, "close");
        headers.add(Headers.TRANSFER_ENCODING, "chunked");
        headers.add(Headers.KEEP_ALIVE, "timeout=5");
        headers.add(Headers.UPGRADE, "h2c");
        headers.add(X_TEST, "abc");

        byte[] encoded = encodeFully(new HpackEncoder(4096), headers);

        assertArrayEquals(new byte[]{
                0x40, 0x06, 'x', '-', 't', 'e', 's', 't', 0x03, 'a', 'b', 'c'
        }, encoded);
        List<DecodedHeader> decoded = decode(encoded);
        assertEquals(1, decoded.size());
        assertEquals("x-test", decoded.get(0).name.toString());
        assertEquals("abc", decoded.get(0).value);
    }

    @Test
    void dropsConnectionSpecificHeadersEvenWhenTheyAreTheOnlyHeaders() {
        HeaderMap headers = new HeaderMap();
        headers.add(Headers.CONNECTION, "close");
        headers.add(Headers.KEEP_ALIVE, "timeout=5");

        assertArrayEquals(new byte[0], encodeFully(new HpackEncoder(4096), headers));
    }

    @Test
    void replacesCarriageReturnsAndLineFeedsInValues() throws Exception {
        String unsafeValue = "a\r\nb\rc\n";
        byte[] encoded = encodeFully(new HpackEncoder(4096), headers("x-test", unsafeValue));

        assertArrayEquals(new byte[]{
                0x40, 0x06, 'x', '-', 't', 'e', 's', 't', 0x07,
                'a', ' ', ' ', 'b', ' ', 'c', ' '
        }, encoded);

        List<DecodedHeader> decoded = decode(encoded);
        assertEquals(1, decoded.size());
        assertEquals("a  b c ", decoded.get(0).value);
    }

    @Test
    void defaultHeaderFunctionAvoidsIndexingContentLengthAndDate() throws Exception {
        HpackEncoder.HpackHeaderFunction function = HpackEncoder.DEFAULT_HEADER_FUNCTION;

        assertFalse(function.shouldUseIndexing(Headers.CONTENT_LENGTH, "42"));
        assertFalse(function.shouldUseIndexing(Headers.DATE, "Mon, 01 Jan 2024 00:00:00 GMT"));
        assertTrue(function.shouldUseIndexing(X_TEST, "abc"));
    }

    @Test
    void defaultHeaderFunctionUsesHuffmanOnlyForValuesAndNamesLongerThanTenCharacters() {
        HpackEncoder.HpackHeaderFunction function = HpackEncoder.DEFAULT_HEADER_FUNCTION;

        assertFalse(function.shouldUseHuffman(X_TEST, "0123456789"));
        assertTrue(function.shouldUseHuffman(X_TEST, "01234567890"));
        assertFalse(function.shouldUseHuffman(new HttpString("1234567890")));
        assertTrue(function.shouldUseHuffman(new HttpString("12345678901")));
    }

    @Test
    void appliesDefaultHuffmanThresholdToHeaderValues() {
        byte[] tenCharacterValue = encodeFully(new HpackEncoder(4096), headers("x-v", "0123456789"));
        ByteBuffer tenWire = ByteBuffer.wrap(tenCharacterValue);
        assertEquals(0x40, tenWire.get() & 0xff);
        readString(tenWire); // literal name
        assertFalse(readString(tenWire).huffman);

        byte[] elevenCharacterValue = encodeFully(new HpackEncoder(4096), headers("x-v", "01234567890"));
        ByteBuffer elevenWire = ByteBuffer.wrap(elevenCharacterValue);
        assertEquals(0x40, elevenWire.get() & 0xff);
        readString(elevenWire); // literal name
        assertTrue(readString(elevenWire).huffman);
    }

    @Test
    void appliesDefaultHuffmanThresholdToHeaderNames() {
        byte[] tenCharacterName = encodeFully(new HpackEncoder(4096), headers("x123456789", "v"));
        ByteBuffer tenWire = ByteBuffer.wrap(tenCharacterName);
        assertEquals(0x40, tenWire.get() & 0xff);
        assertFalse(readString(tenWire).huffman);

        byte[] elevenCharacterName = encodeFully(new HpackEncoder(4096), headers("x1234567890", "v"));
        ByteBuffer elevenWire = ByteBuffer.wrap(elevenCharacterName);
        assertEquals(0x40, elevenWire.get() & 0xff);
        assertTrue(readString(elevenWire).huffman);
    }

    @Test
    void customHeaderFunctionCanDisableBothIndexingAndHuffman() {
        HpackEncoder encoder = new HpackEncoder(4096, NO_INDEXING_OR_HUFFMAN);
        HeaderMap headers = headers("x-test", "abcdefghijkl");

        byte[] expected = new byte[]{
                0x10, 0x06, 'x', '-', 't', 'e', 's', 't',
                0x0c, 'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l'
        };
        assertArrayEquals(expected, encodeFully(encoder, headers));
        // Nothing was added to the dynamic table, so a second encoding is identical.
        assertArrayEquals(expected, encodeFully(encoder, headers));
    }

    @Test
    void customHeaderFunctionCanForceHuffmanEncoding() throws Exception {
        byte[] encoded = encodeFully(new HpackEncoder(4096, ALWAYS_HUFFMAN), headers("x-test", "abc"));
        ByteBuffer wire = ByteBuffer.wrap(encoded);

        assertEquals(0x40, wire.get() & 0xff);
        assertTrue(readString(wire).huffman);
        assertTrue(readString(wire).huffman);

        List<DecodedHeader> decoded = decode(encoded);
        assertEquals(1, decoded.size());
        assertEquals("x-test", decoded.get(0).name.toString());
        assertEquals("abc", decoded.get(0).value);
    }

    @Test
    void doesNotIndexContentLengthOrDateByDefault() throws Exception {
        HpackEncoder encoder = new HpackEncoder(4096);
        HeaderMap contentLength = headers("content-length", "42");

        byte[] contentLengthBytes = encodeFully(encoder, contentLength);
        assertArrayEquals(new byte[]{
                0x1f, 0x0d, 0x02, '4', '2'
        }, contentLengthBytes);
        assertArrayEquals(contentLengthBytes, encodeFully(encoder, contentLength));
        assertTrue(decode(contentLengthBytes).get(0).neverIndex);

        byte[] dateBytes = encodeFully(encoder, headers("date", "Mon"));
        assertArrayEquals(new byte[]{
                0x1f, 0x12, 0x03, 'M', 'o', 'n'
        }, dateBytes);
        assertTrue(decode(dateBytes).get(0).neverIndex);
    }

    @Test
    void emitsTableSizeUpdatesBeforeHeaders() throws Exception {
        HpackEncoder encoder = new HpackEncoder(4096);
        encoder.setMaxTableSize(64);

        byte[] encoded = encodeFully(encoder, headers(":status", "200"));

        assertArrayEquals(new byte[]{(byte) 0x3f, 0x21, (byte) 0x88}, encoded);

        HpackDecoder decoder = new HpackDecoder();
        DecodingEmitter emitter = new DecodingEmitter();
        decoder.setHeaderEmitter(emitter);
        decoder.decode(ByteBuffer.wrap(encoded), false);
        assertEquals(1, emitter.headers.size());
        assertEquals(":status", emitter.headers.get(0).name.toString());
        assertEquals("200", emitter.headers.get(0).value);
    }

    @Test
    void emitsOnlyTheLatestTableSizeUpdateWhenItWasNotReducedFirst() {
        HpackEncoder encoder = new HpackEncoder(4096);
        encoder.setMaxTableSize(128);

        assertArrayEquals(new byte[]{(byte) 0x3f, 0x61}, encodeFully(encoder, new HeaderMap()));
        // A completed encoding consumes the pending update.
        assertArrayEquals(new byte[0], encodeFully(encoder, new HeaderMap()));
    }

    @Test
    void emitsTheMinimumAndThenTheLatestTableSizeUpdate() throws Exception {
        HpackEncoder encoder = new HpackEncoder(4096);
        encoder.setMaxTableSize(128);
        encoder.setMaxTableSize(64);
        encoder.setMaxTableSize(96);

        byte[] encoded = encodeFully(encoder, new HeaderMap());
        assertArrayEquals(new byte[]{
                (byte) 0x3f, 0x21,
                (byte) 0x3f, 0x41
        }, encoded);

        // A decoder accepts both dynamic-table-size updates before any headers.
        HpackDecoder decoder = new HpackDecoder();
        decoder.setHeaderEmitter(new DecodingEmitter());
        decoder.decode(ByteBuffer.wrap(encoded), false);
    }

    @Test
    void shrinkingTheTableEvictsEntriesBeforeTheNextHeaderIsEncoded() throws Exception {
        HpackEncoder encoder = new HpackEncoder(80);
        encodeFully(encoder, headers("x-one", "aaa"));
        encodeFully(encoder, headers("x-two", "bbb"));

        encoder.setMaxTableSize(35);
        byte[] encoded = encodeFully(encoder, headers("x-two", "bbb"));

        assertArrayEquals(new byte[]{
                (byte) 0x3f, 0x04,
                0x10, 0x05, 'x', '-', 't', 'w', 'o', 0x03, 'b', 'b', 'b'
        }, encoded);

        List<DecodedHeader> decoded = decode(encoded);
        assertEquals(1, decoded.size());
        assertEquals("x-two", decoded.get(0).name.toString());
        assertEquals("bbb", decoded.get(0).value);
        assertTrue(decoded.get(0).neverIndex);
    }

    @Test
    void returnsOverflowWithoutWritingWhenTheTargetIsTooSmallAndResumesLater() throws Exception {
        HpackEncoder encoder = new HpackEncoder(4096);
        HeaderMap headers = headers("x-test", "abc");

        ByteBuffer tiny = ByteBuffer.allocate(1);
        assertEquals(HpackEncoder.State.OVERFLOW, encoder.encode(headers, tiny));
        assertEquals(0, tiny.position());

        ByteBuffer target = ByteBuffer.allocate(64);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, target));
        byte[] encoded = bytes(target);
        assertArrayEquals(new byte[]{
                0x40, 0x06, 'x', '-', 't', 'e', 's', 't', 0x03, 'a', 'b', 'c'
        }, encoded);

        List<DecodedHeader> decoded = decode(encoded);
        assertEquals(1, decoded.size());
        assertEquals("abc", decoded.get(0).value);
    }

    @Test
    void canResumeAcrossManySmallTargetBuffersIncludingMultipleValues() throws Exception {
        HpackEncoder encoder = new HpackEncoder(4096);
        HeaderMap headers = new HeaderMap();
        headers.add(new HttpString(":method"), "GET");
        headers.add(X_ALPHA, "one");
        headers.add(X_BETA, "two");
        headers.add(X_BETA, "three");

        ByteArrayOutputStream output = new ByteArrayOutputStream();
        HpackEncoder.State state;
        int calls = 0;
        do {
            ByteBuffer target = ByteBuffer.allocate(1);
            state = encoder.encode(headers, target);
            output.write(target.array(), 0, target.position());
            calls++;
            assertTrue(calls < 1000, "encoder did not make progress");
        } while (state == HpackEncoder.State.OVERFLOW);

        assertEquals(HpackEncoder.State.COMPLETE, state);
        List<DecodedHeader> decoded = decode(output.toByteArray());

        assertEquals(4, decoded.size());
        assertEquals(":method", decoded.get(0).name.toString());
        assertEquals("GET", decoded.get(0).value);
        assertTrue(containsHeader(decoded, "x-alpha", "one"));
        assertTrue(containsHeader(decoded, "x-beta", "two"));
        assertTrue(containsHeader(decoded, "x-beta", "three"));
    }

    @Test
    void rejectsAChangedHeaderMapWhileAnEncodingIsInProgress() {
        HpackEncoder encoder = new HpackEncoder(4096);
        HeaderMap original = headers("x-test", "abc");
        HeaderMap different = headers("x-other", "def");

        ByteBuffer tiny = ByteBuffer.allocate(1);
        assertEquals(HpackEncoder.State.OVERFLOW, encoder.encode(original, tiny));

        assertThrows(IllegalStateException.class,
                () -> encoder.encode(different, ByteBuffer.allocate(64)));
    }

    @Test
    void emptyHeaderMapCompletesWithoutProducingBytes() {
        ByteBuffer target = ByteBuffer.allocate(32);
        assertEquals(HpackEncoder.State.COMPLETE, new HpackEncoder(4096).encode(new HeaderMap(), target));
        assertEquals(0, target.position());
    }

    private static boolean containsHeader(List<DecodedHeader> headers, String name, String value) {
        for (DecodedHeader header : headers) {
            if (header.name.toString().equals(name) && header.value.equals(value)) {
                return true;
            }
        }
        return false;
    }

    private static HeaderMap headers(String name, String... values) {
        HeaderMap headers = new HeaderMap();
        HttpString headerName = new HttpString(name);
        for (String value : values) {
            headers.add(headerName, value);
        }
        return headers;
    }

    private static byte[] encodeFully(HpackEncoder encoder, HeaderMap headers) {
        ByteBuffer target = ByteBuffer.allocate(8192);
        assertEquals(HpackEncoder.State.COMPLETE, encoder.encode(headers, target));
        return bytes(target);
    }

    private static byte[] bytes(ByteBuffer target) {
        target.flip();
        byte[] result = new byte[target.remaining()];
        target.get(result);
        return result;
    }

    private static byte[] octets(int... values) {
        byte[] result = new byte[values.length];
        for (int i = 0; i < values.length; ++i) {
            result[i] = (byte) values[i];
        }
        return result;
    }

    private static List<DecodedHeader> decode(byte[] encoded) throws HpackException {
        HpackDecoder decoder = new HpackDecoder();
        DecodingEmitter emitter = new DecodingEmitter();
        decoder.setHeaderEmitter(emitter);
        decoder.decode(ByteBuffer.wrap(encoded), false);
        return emitter.headers;
    }

    private static WireString readString(ByteBuffer encoded) {
        assertTrue(encoded.hasRemaining());
        boolean huffman = (encoded.get(encoded.position()) & 0x80) != 0;
        int length = Hpack.decodeInteger(encoded, 7);
        assertTrue(length >= 0);
        byte[] content = new byte[length];
        encoded.get(content);
        return new WireString(huffman, content);
    }

    private static final class WireString {
        private final boolean huffman;
        private final byte[] content;

        private WireString(boolean huffman, byte[] content) {
            this.huffman = huffman;
            this.content = content;
        }

        @Override
        public String toString() {
            return new String(content, StandardCharsets.ISO_8859_1);
        }
    }

    private static final class DecodedHeader {
        private final HttpString name;
        private final String value;
        private final boolean neverIndex;

        private DecodedHeader(HttpString name, String value, boolean neverIndex) {
            this.name = name;
            this.value = value;
            this.neverIndex = neverIndex;
        }
    }

    private static final class DecodingEmitter implements HpackDecoder.HeaderEmitter {
        private final List<DecodedHeader> headers = new ArrayList<>();

        @Override
        public void emitHeader(HttpString name, String value, boolean neverIndex) {
            assertNotNull(name);
            headers.add(new DecodedHeader(name, value, neverIndex));
        }
    }
}
