        buf.put((byte)0);
        Http2ProtocolUtils.putInt(buf, 0); //stream id
        Http2ProtocolUtils.putInt(buf, lastGoodStreamId);
        Http2ProtocolUtils.putInt(buf, status);
        buf.flip();
        return new SendFrameHeader(new ImmediatePooledByteBuffer(buf));
    }

