/**
 * Tests the externally observable behavior of {@link Http2Channel}.
 */
class Http2ChannelTests {

    private static XnioWorker worker;
    private static XnioIoThread ioThread;

    private ChannelPipe<StreamConnection, StreamConnection> pipe;
    private StreamConnection endpoint;
    private StreamConnection peer;
    private ByteBufferPool bufferPool;
    private Http2Channel channel;

    @BeforeAll
    static void createWorker() throws IOException {
        worker = Xnio.getInstance().createWorker(OptionMap.create(Options.WORKER_IO_THREADS, 1));
        ioThread = worker.getIoThread();
    }

    @AfterAll
    static void stopWorker() throws InterruptedException {
        worker.shutdownNow();
        worker.awaitTermination(5, TimeUnit.SECONDS);
    }

    @BeforeEach
    void setUp() throws IOException {
        pipe = worker.createFullDuplexPipeConnection();
        endpoint = pipe.getLeftSide();
        peer = pipe.getRightSide();
        bufferPool = new DefaultByteBufferPool(false, 1024);
    }

    @AfterEach
    void tearDown() {
        if (channel != null) {
            IoUtils.safeClose(channel);
            channel = null;
        }
        IoUtils.safeClose(endpoint);
        IoUtils.safeClose(peer);
        bufferPool.close();
    }

    @Test
    void serverChannelExposesDefaultConfiguration() {
        runOnIoThread(() -> {
            Http2Channel server = newServer(false, OptionMap.EMPTY);

            assertFalse(server.isClient());
            assertEquals(3, server.getHttp2Version());
            assertEquals(UndertowOptions.DEFAULT_HTTP2_SETTINGS_INITIAL_WINDOW_SIZE, server.getInitialSendWindowSize());
            assertEquals(UndertowOptions.DEFAULT_HTTP2_SETTINGS_INITIAL_WINDOW_SIZE, server.getInitialReceiveWindowSize());
            assertEquals(-1, server.getSendMaxConcurrentStreams());
            assertEquals(UndertowOptions.DEFAULT_HTTP2_SETTINGS_MAX_CONCURRENT_STREAMS, server.getReceiveMaxConcurrentStreams());
            assertEquals(Http2Channel.DEFAULT_MAX_FRAME_SIZE, server.getSendMaxFrameSize());
            assertEquals(Http2Channel.DEFAULT_MAX_FRAME_SIZE, server.getReceiveMaxFrameSize());
            assertEquals(Http2OpenListener.HTTP2, server.getProtocol());
            assertTrue(server.isPushEnabled());
            assertFalse(server.isThisGoneAway());
            assertFalse(server.isPeerGoneAway());
            assertNull(server.getSslSession());
            assertTrue(server.isOpen());
        });
    }

    @Test
    void constructorAppliesOptionsToChannel() {
        runOnIoThread(() -> {
            OptionMap options = OptionMap.builder()
                    .set(UndertowOptions.HTTP2_SETTINGS_INITIAL_WINDOW_SIZE, 1234)
                    .set(UndertowOptions.HTTP2_SETTINGS_MAX_CONCURRENT_STREAMS, 7)
                    .set(UndertowOptions.HTTP2_SETTINGS_MAX_FRAME_SIZE, 32768)
                    .set(UndertowOptions.HTTP2_SETTINGS_ENABLE_PUSH, false)
                    .set(UndertowOptions.MAX_HEADERS, 5)
                    .getMap();
            Http2Channel server = new Http2Channel(endpoint, "custom-protocol", bufferPool, null, false, false, options);
            channel = server;

            assertEquals(1234, server.getInitialReceiveWindowSize());
            assertEquals(7, server.getReceiveMaxConcurrentStreams());
            assertEquals(32768, server.getReceiveMaxFrameSize());
            assertFalse(server.isPushEnabled());
            assertEquals("custom-protocol", server.getProtocol());
            assertEquals(5, server.getMaxHeaders());
        });
    }

    @Test
    void constructorRejectsNullConnectedChannel() {
        assertThrows(IllegalArgumentException.class,
                () -> new Http2Channel(null, null, bufferPool, null, false, false, OptionMap.EMPTY));
    }

    @Test
    void constructorRejectsNullBufferPool() {
        assertThrows(IllegalArgumentException.class,
                () -> new Http2Channel(endpoint, null, null, null, false, false, OptionMap.EMPTY));
    }

    @Test
    void constructorAppliesPeerSettingsFromUpgradeBuffer() {
        runOnIoThread(() -> {
            ByteBuffer peerSettings = settingsPayload(
                    Http2Setting.SETTINGS_HEADER_TABLE_SIZE, 8192,
                    Http2Setting.SETTINGS_ENABLE_PUSH, 0,
                    Http2Setting.SETTINGS_MAX_CONCURRENT_STREAMS, 5,
                    Http2Setting.SETTINGS_INITIAL_WINDOW_SIZE, 1234,
                    Http2Setting.SETTINGS_MAX_FRAME_SIZE, 32768);
            Http2Channel server = new Http2Channel(endpoint, "custom", bufferPool, null, false,
                    false, false, peerSettings, OptionMap.EMPTY);
            channel = server;

            assertFalse(server.isPushEnabled());
            assertEquals(5, server.getSendMaxConcurrentStreams());
            assertEquals(1234, server.getInitialSendWindowSize());
            assertEquals(32768, server.getSendMaxFrameSize());
            assertEquals("custom", server.getProtocol());
            assertFalse(server.isThisGoneAway());
        });
    }

    @Test
    void clientChannelWritesPrefaceThenSettings() throws IOException {
        runOnIoThread(() -> {
            Http2Channel client = newClient(false, OptionMap.EMPTY);
            assertEquals(Http2OpenListener.HTTP2, client.getProtocol());
            assertEquals("1", client.getProtocolRequestId());

            ByteBuffer preface = readBytes(Http2Channel.PREFACE_BYTES.length);
            byte[] actualPreface = new byte[preface.remaining()];
            preface.get(actualPreface);
            assertArrayEquals(Http2Channel.PREFACE_BYTES, actualPreface);

            Frame settingsFrame = readFrame();
            assertEquals(4, settingsFrame.type);
            assertEquals(0, settingsFrame.flags);
            assertEquals(0, settingsFrame.streamId);
            Map<Integer, Long> settings = parseSettings(settingsFrame.payload);
            assertEquals(Long.valueOf(4096), settings.get(Http2Setting.SETTINGS_HEADER_TABLE_SIZE));
            assertEquals(Long.valueOf(1), settings.get(Http2Setting.SETTINGS_ENABLE_PUSH));
            assertEquals(Long.valueOf(Http2Channel.DEFAULT_MAX_FRAME_SIZE),
                    settings.get(Http2Setting.SETTINGS_MAX_FRAME_SIZE));
            assertEquals(Long.valueOf(UndertowOptions.DEFAULT_HTTP2_SETTINGS_INITIAL_WINDOW_SIZE),
                    settings.get(Http2Setting.SETTINGS_INITIAL_WINDOW_SIZE));
            assertEquals(Long.valueOf(20000), settings.get(Http2Setting.SETTINGS_MAX_HEADER_LIST_SIZE));
            assertNoMoreData();
        });
    }

    @Test
    void serverChannelDoesNotWriteBeforeUse() {
        runOnIoThread(() -> {
            newServer(false, OptionMap.EMPTY);
            assertNoMoreData();
        });
    }

    @Test
    void clientUpgradeReservesFirstStreamAndUsesNextOddStreamId() throws IOException {
        runOnIoThread(() -> {
            Http2Channel client = newClient(true, OptionMap.EMPTY);
            assertEquals("3", client.getProtocolRequestId());
            readBytes(Http2Channel.PREFACE_BYTES.length);
            readFrame();

            Http2HeadersStreamSinkChannel stream = client.createStream(new HeaderMap());
            assertEquals(3, stream.getStreamId());
            assertEquals("5", client.getProtocolRequestId());
        });
    }

    @Test
    void createStreamUsesFirstOddStreamIdAndAdvancesRequestId() throws IOException {
        runOnIoThread(() -> {
            Http2Channel client = newClient(false, OptionMap.EMPTY);
            readBytes(Http2Channel.PREFACE_BYTES.length);
            readFrame();

            Http2HeadersStreamSinkChannel stream = client.createStream(new HeaderMap());
            assertEquals(1, stream.getStreamId());
            assertEquals("3", client.getProtocolRequestId());
        });
    }

    @Test
    void createStreamIsRejectedOnServer() {
        runOnIoThread(() -> {
            Http2Channel server = newServer(false, OptionMap.EMPTY);
            IOException exception = assertThrows(IOException.class, () -> server.createStream(new HeaderMap()));
            assertEquals(UndertowMessages.MESSAGES.headersStreamCanOnlyBeCreatedByClient().getMessage(),
                    exception.getMessage());
        });
    }

    @Test
    void createStreamEnforcesMaxConcurrentStreamLimit() throws IOException {
        runOnIoThread(() -> {
            Http2Channel client = newClient(false, OptionMap.EMPTY);
            client.setSendMaxConcurrentStreams(1);
            assertEquals(1, client.getSendMaxConcurrentStreams());

            assertEquals(1, client.createStream(new HeaderMap()).getStreamId());
            IOException exception = assertThrows(IOException.class, () -> client.createStream(new HeaderMap()));
            assertEquals(UndertowMessages.MESSAGES.streamLimitExceeded().getMessage(), exception.getMessage());
        });
    }

    @Test
    void createStreamIsRejectedAfterGoAway() {
        runOnIoThread(() -> {
            Http2Channel client = newClient(false, OptionMap.EMPTY);
            client.sendGoAway(Http2Channel.ERROR_NO_ERROR);
            assertFalse(client.isOpen());
            assertThrows(ClosedChannelException.class, () -> client.createStream(new HeaderMap()));
        });
    }

    @Test
    void createInitialUpgradeResponseStreamCreatesStreamOneOnlyOnce() {
        runOnIoThread(() -> {
            Http2Channel server = newServer(false, OptionMap.EMPTY);
            Http2HeadersStreamSinkChannel stream = server.createInitialUpgradeResponseStream();
            assertEquals(1, stream.getStreamId());

            assertThrows(IllegalStateException.class, server::createInitialUpgradeResponseStream);

            server.sendGoAway(Http2Channel.ERROR_NO_ERROR);
            Frame goAway = readFrame();
            assertEquals(7, goAway.type);
            assertEquals(1, goAway.intAt(0));
            assertEquals(Http2Channel.ERROR_NO_ERROR, goAway.intAt(4));
        });
