void addToAttachmentListAppendsMultipleValues() {
    // The Attachable contract says this method appends. Http2Channel creates its list with
    // Object.class, so a second add fails while ListAttachmentKey.cast validates the element type.
    runOnIoThread(() -> {
        Http2Channel server = newServer(false, OptionMap.EMPTY);
        AttachmentKey<AttachmentList<String>> key = AttachmentKey.createList(String.class);

        server.addToAttachmentList(key, "one");
        assertDoesNotThrow(() -> server.addToAttachmentList(key, "two"),
                "addToAttachmentList should append another value instead of failing");

        assertEquals(Arrays.asList("one", "two"), server.getAttachmentList(key));
    });
