            assertEquals(2, frames.size());
            assertEquals(FRAME_TYPE_HEADERS, frames.get(0).type());
            assertEquals(FRAME_TYPE_DATA, frames.get(1).type());
            assertEquals(0, frames.get(1).flags() & DATA_FLAG_END_STREAM);

            List<Frame> trailerFrames = parseFrames(frameHeader.getTrailer());
            assertEquals(1, trailerFrames.size());
            Frame trailer = trailerFrames.get(0);
            assertEquals(FRAME_TYPE_HEADERS, trailer.type());
            assertEquals(HEADERS_FLAG_END_HEADERS | HEADERS_FLAG_END_STREAM, trailer.flags());
            assertEquals(STREAM_ID, trailer.streamId());
            HeaderMap decoded = decodeHeaderBlocks(trailerFrames);
            assertEquals("abc123", decoded.getFirst(new HttpString("x-checksum")));
        } finally {
            frameHeader.getByteBuffer().close();
        }
    }

    @Test
    void emptyTrailerMapIsIgnoredAndFinalDataFrameEndsTheStream() throws Exception {
