        TestChannel channel = newChannel(new HeaderMap(), FRAME_TYPE_HEADERS, 1024, 0, DEFAULT_WINDOW);
        channel.setTrailersProducer(() -> {
            calls.incrementAndGet();
            return new HeaderMap();
        });

        channel.write(ByteBuffer.wrap(new byte[]{1, 2}));
        SendFrameHeader frameHeader = channel.createFrameHeaderForTest();
        try {
            assertEquals(0, calls.get());
            assertNull(frameHeader.getTrailer());
        } finally {
