            assertEquals(1, frames.size());
            assertEquals(HEADERS_FLAG_END_HEADERS | HEADERS_FLAG_END_STREAM, frames.get(0).flags());
        } finally {
            frameHeader.getByteBuffer().close();
        }
    }

    @Test
    void largeHeadersAreSplitIntoContinuationFramesAndRemainDecodable() throws Exception {
        HeaderMap headers = new HeaderMap();
        for (int i = 0; i < 12; i++) {
            headers.put(new HttpString("x-large-" + i), "value-" + i + "-012345678901234567890123456789");
        }
        TestChannel channel = newChannel(headers, FRAME_TYPE_HEADERS, 32, 0, DEFAULT_WINDOW);

        SendFrameHeader frameHeader = channel.createFrameHeaderForTest();
        try {
            List<Frame> frames = parseFrames(frameHeader.getByteBuffer().getBuffer());
            assertTrue(frames.size() > 1);
            assertEquals(FRAME_TYPE_HEADERS, frames.get(0).type());
            assertEquals(0, frames.get(0).flags() & HEADERS_FLAG_END_HEADERS);
            for (int i = 1; i < frames.size(); i++) {
                assertEquals(FRAME_TYPE_CONTINUATION, frames.get(i).type());
                assertEquals(STREAM_ID, frames.get(i).streamId());
                if (i == frames.size() - 1) {
                    assertEquals(HEADERS_FLAG_END_HEADERS, frames.get(i).flags());
                } else {
                    assertEquals(0, frames.get(i).flags());
                }
            }
            HeaderMap decoded = decodeHeaderBlocks(frames);
            for (int i = 0; i < 12; i++) {
                assertEquals("value-" + i + "-012345678901234567890123456789",
                        decoded.getFirst(new HttpString("x-large-" + i)));
            }
        } finally {
            frameHeader.getByteBuffer().close();
        }
    }

    @Test
    void completionListenerIsInvokedOnceAfterAFinalStreamFlush() throws Exception {
        TestChannel channel = newChannel(new HeaderMap(), FRAME_TYPE_HEADERS, 1024, 0, DEFAULT_WINDOW);
        AtomicInteger invocations = new AtomicInteger();
        ChannelListener<Http2DataStreamSinkChannel> listener = ignored -> invocations.incrementAndGet();
        channel.setCompletionListener(listener);

        channel.completeFlushForTest(true);
        channel.flush();
        channel.flush();

        assertEquals(1, invocations.get());
        assertNull(channel.getCompletionListener());
    }

    @Test
    void completionListenerIsRetainedUntilAFinalStreamFlush() throws Exception {
        TestChannel channel = newChannel(new HeaderMap(), FRAME_TYPE_HEADERS, 1024, 0, DEFAULT_WINDOW);
        AtomicInteger invocations = new AtomicInteger();
        ChannelListener<Http2DataStreamSinkChannel> listener = ignored -> invocations.incrementAndGet();
        channel.setCompletionListener(listener);

        channel.completeFlushForTest(false);
        channel.flush();

        assertEquals(0, invocations.get());
        assertSame(listener, channel.getCompletionListener());
    }

    @Test
    void closedChannelNotifiesCompletionListenerOnNextWriteAndOnlyOnce() throws Exception {
        TestChannel channel = newChannel(new HeaderMap(), FRAME_TYPE_HEADERS, 1024, 0, DEFAULT_WINDOW);
        AtomicInteger invocations = new AtomicInteger();
        channel.setCompletionListener(ignored -> invocations.incrementAndGet());

        channel.close();

        assertThrows(ClosedChannelException.class, () -> channel.write(ByteBuffer.wrap(new byte[]{1})));
        assertEquals(1, invocations.get());
        assertNull(channel.getCompletionListener());
        assertThrows(ClosedChannelException.class, () -> channel.write(ByteBuffer.wrap(new byte[]{2})));
        assertEquals(1, invocations.get());
    }

    private TestChannel newChannel(HeaderMap headers, int frameType, int bufferSize, int padding, int flowControl) {
        mockedChannel = createNiceMock(Http2Channel.class);
        encoder = new HpackEncoder(Hpack.DEFAULT_TABLE_SIZE);
        bufferPool = new DefaultByteBufferPool(false, bufferSize, 0, 0);

        expect(mockedChannel.getEncoder()).andReturn(encoder).anyTimes();
        expect(mockedChannel.getBufferPool()).andReturn(bufferPool).anyTimes();
        expect(mockedChannel.getInitialSendWindowSize()).andReturn(DEFAULT_WINDOW).anyTimes();
        expect(mockedChannel.getSendMaxFrameSize()).andReturn(16384).anyTimes();
        expect(mockedChannel.getPaddingBytes()).andReturn(padding).anyTimes();
        expect(mockedChannel.grabFlowControlBytes(anyInt())).andAnswer(() -> {
            int requested = (Integer) getCurrentArguments()[0];
            return Math.min(requested, flowControl);
        }).anyTimes();
        replay(mockedChannel);

        return new TestChannel(mockedChannel, STREAM_ID, headers, frameType);
    }

    private static HeaderMap decodeHeaderBlocks(List<Frame> frames) throws HpackException {
        int length = 0;
        for (Frame frame : frames) {
            if (frame.type() == FRAME_TYPE_HEADERS || frame.type() == FRAME_TYPE_CONTINUATION) {
                length += frame.payload().length;
            }
        }
        ByteBuffer block = ByteBuffer.allocate(length);
        for (Frame frame : frames) {
            if (frame.type() == FRAME_TYPE_HEADERS || frame.type() == FRAME_TYPE_CONTINUATION) {
                block.put(frame.payload());
            }
        }
        block.flip();

        HeaderMap decoded = new HeaderMap();
        HpackDecoder decoder = new HpackDecoder(Hpack.DEFAULT_TABLE_SIZE);
        decoder.setHeaderEmitter((name, value, neverIndex) -> decoded.put(name, value));
        decoder.decode(block, false);
        assertFalse(block.hasRemaining());
        return decoded;
    }

    private static List<Frame> parseFrames(ByteBuffer source) {
        ByteBuffer buffer = source.duplicate();
        List<Frame> frames = new ArrayList<>();
        while (buffer.hasRemaining()) {
            if (buffer.remaining() < 9) {
                throw new AssertionError("Truncated HTTP/2 frame header: " + buffer.remaining() + " bytes");
            }
            int length = ((buffer.get() & 0xFF) << 16) | ((buffer.get() & 0xFF) << 8) | (buffer.get() & 0xFF);
            int type = buffer.get() & 0xFF;
            int flags = buffer.get() & 0xFF;
            int streamId = ((buffer.get() & 0x7F) << 24) | ((buffer.get() & 0xFF) << 16)
                    | ((buffer.get() & 0xFF) << 8) | (buffer.get() & 0xFF);
            if (buffer.remaining() < length) {
                throw new AssertionError("Truncated HTTP/2 frame payload");
            }
            byte[] payload = new byte[length];
            buffer.get(payload);
            frames.add(new Frame(length, type, flags, streamId, payload));
        }
        return frames;
    }

    private record Frame(int length, int type, int flags, int streamId, byte[] payload) {
    }

    private static final class TestChannel extends Http2DataStreamSinkChannel {

        private TestChannel(Http2Channel channel, int streamId, HeaderMap headers, int frameType) {
            super(channel, streamId, headers, frameType);
        }

        SendFrameHeader createFrameHeaderForTest() {
            return createFrameHeaderImpl();
        }

        void completeFlushForTest(boolean finalFrame) {
            handleFlushComplete(finalFrame);
        }
    }
}
