import io.undertow.util.HeaderMap;
import io.undertow.util.Headers;
import io.undertow.util.HttpString;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.xnio.ChannelListener;

class Http2DataStreamSinkChannelTests {

    private static final int STREAM_ID = 3;
    private static final int DEFAULT_WINDOW = 65535;

    private Http2Channel mockedChannel;
    private ByteBufferPool bufferPool;
    private HpackEncoder encoder;

    @AfterEach
    void cleanUp() {
        if (bufferPool != null) {
            bufferPool.close();
        }
    }

    @Test
    void exposesHeadersAndTrailersProducer() {
        HeaderMap headers = new HeaderMap();
        headers.put(Http2Channel.STATUS, "200");
        TestChannel channel = newChannel(headers, FRAME_TYPE_HEADERS, 1024, 0, DEFAULT_WINDOW);

        assertSame(headers, channel.getHeaders());
        assertEquals("200", channel.getHeaders().getFirst(Http2Channel.STATUS));

        Http2DataStreamSinkChannel.TrailersProducer producer = HeaderMap::new;
        assertNull(channel.getTrailersProducer());
        channel.setTrailersProducer(producer);
        assertSame(producer, channel.getTrailersProducer());
        channel.setTrailersProducer(null);
        assertNull(channel.getTrailersProducer());
    }

    @Test
    void firstWriteProducesAnEndHeadersFrameWithEncodedRequestHeaders() throws Exception {
        HeaderMap headers = new HeaderMap();
        headers.put(Http2Channel.STATUS, "200");
        headers.put(Headers.CONTENT_TYPE, "text/plain");
        headers.put(new HttpString("x-test-header"), "test-value");
        TestChannel channel = newChannel(headers, FRAME_TYPE_HEADERS, 1024, 0, DEFAULT_WINDOW);

        SendFrameHeader frameHeader = channel.createFrameHeaderForTest();
        assertNotNull(frameHeader.getByteBuffer());
        try {
            List<Frame> frames = parseFrames(frameHeader.getByteBuffer().getBuffer());
            assertEquals(1, frames.size());
            Frame frame = frames.get(0);
            assertEquals(FRAME_TYPE_HEADERS, frame.type());
            assertEquals(STREAM_ID, frame.streamId());
            assertEquals(HEADERS_FLAG_END_HEADERS, frame.flags());
            assertEquals(frame.payload().length, frame.length());

            HeaderMap decoded = decodeHeaderBlocks(frames);
            assertEquals("200", decoded.getFirst(Http2Channel.STATUS));
            assertEquals("text/plain", decoded.getFirst(Headers.CONTENT_TYPE));
            assertEquals("test-value", decoded.getFirst(new HttpString("x-test-header")));
        } finally {
            frameHeader.getByteBuffer().close();
        }
    }

    @Test
    void writeFinalProducesDataEndStreamAndKeepsPayloadInBodyBuffer() throws Exception {
        TestChannel channel = newChannel(new HeaderMap(), FRAME_TYPE_HEADERS, 1024, 0, DEFAULT_WINDOW);
        byte[] body = "hello".getBytes(StandardCharsets.UTF_8);

        assertEquals(body.length, channel.writeFinal(ByteBuffer.wrap(body)));

        SendFrameHeader frameHeader = channel.createFrameHeaderForTest();
        assertNotNull(frameHeader.getByteBuffer());
        try {
            List<Frame> frames = parseFrames(frameHeader.getByteBuffer().getBuffer());
            assertEquals(2, frames.size());
            assertEquals(FRAME_TYPE_HEADERS, frames.get(0).type());
            assertEquals(HEADERS_FLAG_END_HEADERS, frames.get(0).flags());
            assertEquals(FRAME_TYPE_DATA, frames.get(1).type());
            assertEquals(body.length, frames.get(1).length());
            assertEquals(DATA_FLAG_END_STREAM, frames.get(1).flags());
            assertEquals(STREAM_ID, frames.get(1).streamId());
            assertEquals(0, frameHeader.getRemainingInBuffer());

            ByteBuffer bufferedBody = channel.getBuffer();
            byte[] actual = new byte[bufferedBody.remaining()];
            bufferedBody.duplicate().get(actual);
            assertArrayEquals(body, actual);
        } finally {
            frameHeader.getByteBuffer().close();
        }
    }

    @Test
    void finalFrameWithTrailersEmitsDataThenAHeadersEndStreamTrailer() throws Exception {
        HeaderMap trailers = new HeaderMap();
        trailers.put(new HttpString("x-checksum"), "abc123");
        TestChannel channel = newChannel(new HeaderMap(), FRAME_TYPE_HEADERS, 1024, 0, DEFAULT_WINDOW);
        channel.setTrailersProducer(() -> trailers);

        assertEquals(4, channel.writeFinal(ByteBuffer.wrap("body".getBytes(StandardCharsets.UTF_8))));

        SendFrameHeader frameHeader = channel.createFrameHeaderForTest();
        assertNotNull(frameHeader.getByteBuffer());
        assertNotNull(frameHeader.getTrailer());
        try {
            List<Frame> frames = parseFrames(frameHeader.getByteBuffer().getBuffer());
            assertEquals(2, frames.size());
            assertEquals(FRAME_TYPE_HEADERS, frames.get(0).type());
            assertEquals(FRAME_TYPE_DATA, frames.get(1).type());
            assertEquals(0, frames.get(1).flags() & DATA_FLAG_END_STREAM);

            List<Frame> trailerFrames = parseFrames(frameHeader.getTrailer());
            assertEquals(1, trailerFrames.size());
            Frame trailer = trailerFrames.get(0);
            assertEquals(FRAME_TYPE_HEADERS, trailer.type());
            assertEquals(HEADERS_FLAG_END_HEADERS | HEADERS_FLAG_END_STREAM, trailer.flags());
            assertEquals(STREAM_ID, trailer.streamId());
            HeaderMap decoded = decodeHeaderBlocks(trailerFrames);
            assertEquals("abc123", decoded.getFirst(new HttpString("x-checksum")));
        } finally {
            frameHeader.getByteBuffer().close();
        }
    }

    @Test
    void emptyTrailerMapIsIgnoredAndFinalDataFrameEndsTheStream() throws Exception {
        TestChannel channel = newChannel(new HeaderMap(), FRAME_TYPE_HEADERS, 1024, 0, DEFAULT_WINDOW);
        channel.setTrailersProducer(HeaderMap::new);

        channel.writeFinal(ByteBuffer.wrap(new byte[]{1, 2, 3}));
        SendFrameHeader frameHeader = channel.createFrameHeaderForTest();
        try {
            assertNull(frameHeader.getTrailer());
            List<Frame> frames = parseFrames(frameHeader.getByteBuffer().getBuffer());
            assertEquals(2, frames.size());
            assertEquals(DATA_FLAG_END_STREAM, frames.get(1).flags());
        } finally {
            frameHeader.getByteBuffer().close();
        }
    }

    @Test
    void trailersProducerIsNotConsultedUntilTheFinalFrame() throws Exception {
        AtomicInteger calls = new AtomicInteger();
        TestChannel channel = newChannel(new HeaderMap(), FRAME_TYPE_HEADERS, 1024, 0, DEFAULT_WINDOW);
        channel.setTrailersProducer(() -> {
            calls.incrementAndGet();
            return new HeaderMap();
        });

        channel.write(ByteBuffer.wrap(new byte[]{1, 2}));
        SendFrameHeader frameHeader = channel.createFrameHeaderForTest();
        try {
            assertEquals(0, calls.get());
            assertNull(frameHeader.getTrailer());
        } finally {
            frameHeader.getByteBuffer().close();
        }
    }

    @Test
    void paddedDataFrameCarriesPaddingFlagPadLengthAndPaddingBytes() throws Exception {
        TestChannel channel = newChannel(new HeaderMap(), FRAME_TYPE_HEADERS, 1024, 4, DEFAULT_WINDOW);
        byte[] payload = "data".getBytes(StandardCharsets.UTF_8);

        channel.writeFinal(ByteBuffer.wrap(payload));
        SendFrameHeader frameHeader = channel.createFrameHeaderForTest();
        try {
            List<Frame> frames = parseFrames(frameHeader.getByteBuffer().getBuffer());
            assertEquals(2, frames.size());
            Frame headers = frames.get(0);
            assertEquals(HEADERS_FLAG_END_HEADERS | HEADERS_FLAG_PADDED, headers.flags());
            assertEquals(4, headers.payload()[0] & 0xFF);
            assertTrue(headers.length() >= 5);
            for (int i = headers.payload().length - 4; i < headers.payload().length; i++) {
                assertEquals(0, headers.payload()[i]);
            }

            Frame data = frames.get(1);
            assertEquals(FRAME_TYPE_DATA, data.type());
            assertEquals(DATA_FLAG_END_STREAM | DATA_FLAG_PADDED, data.flags());
            assertEquals(payload.length + 5, data.length());
            assertEquals(4, data.payload()[0] & 0xFF);
            assertNotNull(frameHeader.getTrailer());
            assertEquals(4, frameHeader.getTrailer().remaining());
        } finally {
            frameHeader.getByteBuffer().close();
        }
    }

    @Test
    void exhaustedFlowControlReturnsNoFrameAndLeavesAllPayloadBuffered() throws Exception {
        TestChannel channel = newChannel(new HeaderMap(), FRAME_TYPE_HEADERS, 1024, 0, 0);
        byte[] payload = new byte[]{10, 20, 30, 40, 50};
