        SendFrameHeader frameHeader = channel.createFrameHeaderForTest();
        assertNull(frameHeader.getByteBuffer());
        assertEquals(payload.length, frameHeader.getRemainingInBuffer());
        assertEquals(payload.length, channel.getBuffer().remaining());
