274	    private static Object coerceToType(final String string, final Token token, final Class<?> type, final ExchangeAttributeParser attributeParser) {
275	        if (type.isArray()) {
276	            Object array = Array.newInstance(type.getComponentType(), 1);
277	            Array.set(array, 0, coerceToType(string, token, type.getComponentType(), attributeParser));
278	            return array;
279	        }
280	
281	        if (type == String.class) {
282	            return token.getToken();
283	        } else if (type.equals(Boolean.class) || type.equals(boolean.class)) {
284	            return Boolean.valueOf(token.getToken());
285	        } else if (type.equals(Byte.class) || type.equals(byte.class)) {
286	            return Byte.valueOf(token.getToken());
287	        } else if (type.equals(Character.class) || type.equals(char.class)) {
288	            if (token.getToken().length() != 1) {
289	                throw error(string, token.getPosition(), "Cannot coerce " + token.getToken() + " to a Character");
290	            }
291	            return Character.valueOf(token.getToken().charAt(0));
292	        } else if (type.equals(Short.class) || type.equals(short.class)) {
293	            return Short.valueOf(token.getToken());
294	        } else if (type.equals(Integer.class) || type.equals(int.class)) {
295	            return Integer.valueOf(token.getToken());
296	        } else if (type.equals(Long.class) || type.equals(long.class)) {
297	            return Long.valueOf(token.getToken());
298	        } else if (type.equals(Float.class) || type.equals(float.class)) {
299	            return Float.valueOf(token.getToken());
300	        } else if (type.equals(Double.class) || type.equals(double.class)) {
301	            return Double.valueOf(token.getToken());
302	        } else if (type.equals(ExchangeAttribute.class)) {
303	            return attributeParser.parse(token.getToken());
304	        }
305	
306	        return token.getToken();
