class PredicatedHandlersParserTests {

    private static final ClassLoader CLASS_LOADER = PredicatedHandlersParserTests.class.getClassLoader();

    private static volatile Map<String, Object> lastHandlerConfig;
    private static volatile Map<String, Object> lastPredicateConfig;

    @TempDir
    Path tempDir;

    @AfterEach
    void clearRecordedConfigurations() {
        lastHandlerConfig = null;
        lastPredicateConfig = null;
    }

    @Test
    void parsePredicateEvaluatesBooleanConstantsAndBuiltInPredicates() {
        assertTrue(PredicatedHandlersParser.parsePredicate("true", CLASS_LOADER)
                .resolve(exchange("/anything", Methods.POST_STRING)));
        assertFalse(PredicatedHandlersParser.parsePredicate("false", CLASS_LOADER)
                .resolve(exchange("/anything", Methods.POST_STRING)));

        Predicate path = PredicatedHandlersParser.parsePredicate("path(path='/admin')", CLASS_LOADER);
        assertTrue(path.resolve(exchange("/admin", Methods.GET_STRING)));
        assertFalse(path.resolve(exchange("/public", Methods.GET_STRING)));

        Predicate method = PredicatedHandlersParser.parsePredicate("method(GET)", CLASS_LOADER);
        assertTrue(method.resolve(exchange("/", Methods.GET_STRING)));
        assertFalse(method.resolve(exchange("/", Methods.POST_STRING)));
    }

    @Test
    void parsePredicateHonorsBooleanOperatorPrecedenceAndParentheses() {
        assertTrue(PredicatedHandlersParser.parsePredicate("true or false and false", CLASS_LOADER)
                .resolve(exchange("/", Methods.GET_STRING)));
        assertFalse(PredicatedHandlersParser.parsePredicate("(true or false) and false", CLASS_LOADER)
                .resolve(exchange("/", Methods.GET_STRING)));
        assertTrue(PredicatedHandlersParser.parsePredicate("not (true and false)", CLASS_LOADER)
                .resolve(exchange("/", Methods.GET_STRING)));
    }

    @Test
    void parsePredicateSupportsArraysQuotedValuesAndLegacySquareBrackets() {
        Predicate paths = PredicatedHandlersParser.parsePredicate("path({'/one', '/two words'})", CLASS_LOADER);
        assertTrue(paths.resolve(exchange("/one", Methods.GET_STRING)));
        assertTrue(paths.resolve(exchange("/two words", Methods.GET_STRING)));
        assertFalse(paths.resolve(exchange("/three", Methods.GET_STRING)));

        Predicate methods = PredicatedHandlersParser.parsePredicate("method(GET, POST)", CLASS_LOADER);
        assertTrue(methods.resolve(exchange("/", Methods.GET_STRING)));
        assertTrue(methods.resolve(exchange("/", Methods.POST_STRING)));
        assertFalse(methods.resolve(exchange("/", Methods.PUT_STRING)));

        Predicate legacyMethods = PredicatedHandlersParser.parsePredicate("method[GET]", CLASS_LOADER);
        assertTrue(legacyMethods.resolve(exchange("/", Methods.GET_STRING)));
        assertFalse(legacyMethods.resolve(exchange("/", Methods.POST_STRING)));
    }

    @Test
    void parsePredicateSupportsExchangeAttributes() {
        Predicate equals = PredicatedHandlersParser.parsePredicate("equals(%{METHOD}, GET)", CLASS_LOADER);
        assertTrue(equals.resolve(exchange("/", Methods.GET_STRING)));
        assertFalse(equals.resolve(exchange("/", Methods.POST_STRING)));

        Predicate exists = PredicatedHandlersParser.parsePredicate("exists(%{METHOD})", CLASS_LOADER);
        assertTrue(exists.resolve(exchange("/", Methods.GET_STRING)));
        assertFalse(exists.resolve(new HttpServerExchange(null)));
    }

    @Test
    void parseHandlerBuildsAndAppliesResponseCodeHandler() {
        HandlerWrapper defaultParameter = PredicatedHandlersParser.parseHandler("response-code(204)", CLASS_LOADER);
        HandlerWrapper namedParameter = PredicatedHandlersParser.parseHandler("response-code(value=201)", CLASS_LOADER);

        assertStatusAfterApplying(defaultParameter, 204);
        assertStatusAfterApplying(namedParameter, 201);
    }

    @Test
    void parseHandlerCoercesAllSupportedParameterTypes() throws Exception {
        ClassLoader classLoader = serviceClassLoader(HandlerBuilder.class.getName(),
                AllTypesHandlerBuilder.class);

        PredicatedHandlersParser.parseHandler("all-types("
                + "booleanValue=true, byteValue=7, characterValue=z, shortValue=12, "
                + "integerValue=34, longValue=56, floatValue=1.5, doubleValue=2.25, "
                + "stringValue=hello, attributeValue=%{METHOD}, "
                + "stringsValue={alpha,beta}, integersValue={1,2})", classLoader);

        Map<String, Object> config = lastHandlerConfig;
        assertNotNull(config);
        assertEquals(Boolean.TRUE, config.get("booleanValue"));
        assertEquals(Byte.valueOf((byte) 7), config.get("byteValue"));
        assertEquals(Character.valueOf('z'), config.get("characterValue"));
        assertEquals(Short.valueOf((short) 12), config.get("shortValue"));
        assertEquals(Integer.valueOf(34), config.get("integerValue"));
        assertEquals(Long.valueOf(56L), config.get("longValue"));
        assertEquals(Float.valueOf(1.5f), config.get("floatValue"));
        assertEquals(Double.valueOf(2.25), config.get("doubleValue"));
        assertEquals("hello", config.get("stringValue"));
        assertArrayEquals(new String[]{"alpha", "beta"}, (String[]) config.get("stringsValue"));
        assertArrayEquals(new int[]{1, 2}, (int[]) config.get("integersValue"));

        ExchangeAttribute attribute = assertInstanceOf(ExchangeAttribute.class, config.get("attributeValue"));
        assertEquals("GET", attribute.readAttribute(exchange("/", Methods.GET_STRING)));
    }

    @Test
    void parseHandlerSupportsDefaultParametersAndCoercesScalarsToArrays() throws Exception {
        ClassLoader classLoader = serviceClassLoader(HandlerBuilder.class.getName(),
                DefaultValueHandlerBuilder.class, ArrayValueHandlerBuilder.class);

        PredicatedHandlersParser.parseHandler("default-value(hello)", classLoader);
        assertEquals("hello", lastHandlerConfig.get("value"));

        PredicatedHandlersParser.parseHandler("array-value({one,two})", classLoader);
        assertArrayEquals(new String[]{"one", "two"}, (String[]) lastHandlerConfig.get("value"));

        PredicatedHandlersParser.parseHandler("array-value(only)", classLoader);
        assertArrayEquals(new String[]{"only"}, (String[]) lastHandlerConfig.get("value"));
    }

    @Test
    void parseHandlerRejectsUnknownHandlerUnknownParameterAndMissingRequiredParameter() throws Exception {
