        IllegalArgumentException unknownHandler = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("missing", CLASS_LOADER));
        assertTrue(unknownHandler.getMessage().contains("no handler named missing"));

        IllegalArgumentException unknownParameter = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("default-value(value=hello, nope=1)", classLoader));
        assertTrue(unknownParameter.getMessage().contains("unknown parameter nope"));

        IllegalArgumentException missingRequired = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("required-params(value=hello)", classLoader));
        assertTrue(missingRequired.getMessage().contains("required parameters [other] not provided for handler required-params"));
    }

    @Test
    void parseHandlerRejectsInvalidArrayAndCharacterValues() throws Exception {
        ClassLoader classLoader = serviceClassLoader(HandlerBuilder.class.getName(),
                DefaultValueHandlerBuilder.class, AllTypesHandlerBuilder.class);

        IllegalArgumentException nonArrayValue = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("default-value({a,b})", classLoader));
        assertTrue(nonArrayValue.getMessage().contains("parameter is not an array type value"));

        IllegalArgumentException invalidCharacter = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parseHandler("all-types("
