        assertTrue(error.getMessage().contains("default parameter not supported"));
    }

    @Test
    void parseHandlerDetectsDuplicateHandlerNames() throws Exception {
        ClassLoader classLoader = serviceClassLoader(HandlerBuilder.class.getName(),
                DuplicateHandlerBuilderOne.class, DuplicateHandlerBuilderTwo.class);

        IllegalStateException error = assertThrows(IllegalStateException.class,
