    @Test
    void parsePredicateRejectsUnknownAndInvalidParameters() {
        IllegalArgumentException unknownPredicate = assertThrows(IllegalArgumentException.class,
                () -> PredicatedHandlersParser.parsePredicate("unknown", CLASS_LOADER));
        assertTrue(unknownPredicate.getMessage().contains("no predicate named unknown"));

        IllegalArgumentException missingRequired = assertThrows(IllegalArgumentException.class,
