        assertTrue(unknownParameter.getMessage().contains("unknown parameter nope"));
    }

    @Test
    void parseWrapsBareHandlerInTruePredicate() throws Exception {
        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse("response-code(204)", CLASS_LOADER);

        assertEquals(1, handlers.size());
        PredicatedHandler handler = handlers.get(0);
        assertTrue(handler.getPredicate().resolve(exchange("/somewhere", Methods.DELETE_STRING)));
        assertNull(handler.getElseHandler());
        assertFinalStatus(handlers, "/somewhere", Methods.DELETE_STRING, 204);
    }

    @Test
    void parseSupportsMultipleLinesSemicolonsBlankLinesAndComments() throws Exception {
        String contents = "# leading comment\n"
                + "\n"
                + "path('/alpha') -> response-code(201)\n"
                + "method(POST) -> response-code(202)\n"
                + "path('/gamma') -> response-code(203); method(DELETE) -> response-code(204)";

        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(contents, CLASS_LOADER);

        assertEquals(4, handlers.size());
        assertFinalStatus(handlers, "/alpha", Methods.GET_STRING, 201);
        assertFinalStatus(handlers, "/other", Methods.POST_STRING, 202);
        assertFinalStatus(handlers, "/gamma", Methods.GET_STRING, 203);
        assertFinalStatus(handlers, "/other", Methods.DELETE_STRING, 204);
        assertFinalStatus(handlers, "/other", Methods.GET_STRING, 200);
    }

    @Test
    void parseSupportsElseBranches() throws Exception {
        String contents = "path('/admin') -> response-code(201) else response-code(403)";

        List<PredicatedHandler> handlers = PredicatedHandlersParser.parse(contents, CLASS_LOADER);

        assertEquals(1, handlers.size());
        assertNotNull(handlers.get(0).getElseHandler());
        assertFinalStatus(handlers, "/admin", Methods.GET_STRING, 201);
        assertFinalStatus(handlers, "/public", Methods.GET_STRING, 403);
