                tokenStrings("# comment\nresponse-code(200) -> done"));
        assertEquals(List.of("x", ";", "y", ",", "z", "=", "w", "[", "q", "]", "{", "r", "}"),
                tokenStrings("x ; y,z=w [q] {r}"));
    }

