    private static List<String> tokenStrings(String input) {
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize(input);
        List<String> values = new ArrayList<>();
        for (PredicatedHandlersParser.Token token : tokens) {
            values.add(token.getToken());
        }
        return values;
    }

    private void assertStatusAfterApplying(HandlerWrapper wrapper, int expectedStatus) throws Exception {
        HttpServerExchange exchange = exchange("/", Methods.GET_STRING);
        AtomicInteger invocations = new AtomicInteger();
        wrapper.wrap(next -> invocations.incrementAndGet()).handleRequest(exchange);

        assertEquals(expectedStatus, exchange.getStatusCode());
        assertEquals(1, invocations.get());
    }

    private static void assertFinalStatus(List<PredicatedHandler> handlers, String path, String method,
            int expectedStatus) throws Exception {
        AtomicInteger terminalInvocations = new AtomicInteger();
        PredicatesHandler chain = new PredicatesHandler(next -> terminalInvocations.incrementAndGet(), true);
        for (PredicatedHandler handler : handlers) {
            chain.addPredicatedHandler(handler);
        }

        HttpServerExchange exchange = exchange(path, method);
        chain.handleRequest(exchange);

        assertEquals(expectedStatus, exchange.getStatusCode());
        assertEquals(1, terminalInvocations.get());
    }

    private static HttpServerExchange exchange(String path, String method) {
        HttpServerExchange exchange = new HttpServerExchange(null);
        exchange.setRequestPath(path);
        exchange.setRelativePath(path);
        exchange.setRequestURI(path);
        exchange.setRequestMethod(new HttpString(method));
        return exchange;
    }

    private ClassLoader serviceClassLoader(String serviceType, Class<?>... providers) throws IOException {
        Path serviceRoot = tempDir.resolve(serviceType.replace('.', '_'));
        Path serviceFile = serviceRoot.resolve("META-INF/services").resolve(serviceType);
        Files.createDirectories(serviceFile.getParent());

        List<String> providerNames = new ArrayList<>();
        for (Class<?> provider : providers) {
            providerNames.add(provider.getName());
        }
        Files.writeString(serviceFile, String.join("\n", providerNames), StandardCharsets.UTF_8);

        return new URLClassLoader(new URL[]{serviceRoot.toUri().toURL()}, CLASS_LOADER);
    }

