        assertFalse(PredicatedHandlersParser.parsePredicate("false", CLASS_LOADER)
                .resolve(exchange("/anything", Methods.POST_STRING)));

        Predicate path = PredicatedHandlersParser.parsePredicate("path(path='/admin')", CLASS_LOADER);
        assertTrue(path.resolve(exchange("/admin", Methods.GET_STRING)));
        assertFalse(path.resolve(exchange("/public", Methods.GET_STRING)));

