    @Test
    public void parseStringHandlesSplitLengthAndContent() throws Exception {
        final AjpRequestParser parser = newParser();
        final AjpRequestParseState state = new AjpRequestParseState();

        // first length byte only - the parser has to remember it
        AjpRequestParser.StringHolder holder = parser.parseString(
                ByteBuffer.wrap(new byte[] { 0x00 }), state, AjpRequestParser.StringType.OTHER);
        assertFalse(holder.readComplete);

        holder = parser.parseString(ByteBuffer.wrap(new byte[] { 0x03 }), state, AjpRequestParser.StringType.OTHER);
        assertFalse(holder.readComplete);

        holder = parser.parseString(ByteBuffer.wrap(new byte[] { 'a', 'b' }), state, AjpRequestParser.StringType.OTHER);
        assertFalse(holder.readComplete);
        assertEquals(2, state.getCurrentStringLength());

        holder = parser.parseString(ByteBuffer.wrap(new byte[] { 'c', 0x00 }), state, AjpRequestParser.StringType.OTHER);
        assertTrue(holder.readComplete);
        assertEquals("abc", holder.value);
        assertEquals(0, state.getCurrentStringLength());
    }

    @Test
    public void parseStringFlagsUrlCharacters() throws Exception {
        final AjpRequestParseState state = new AjpRequestParseState();
        final byte[] encoded = "/a%20b".getBytes(StandardCharsets.US_ASCII);
        final byte[] data = new byte[encoded.length + 3];
        data[0] = 0x00;
        data[1] = (byte) encoded.length;
        System.arraycopy(encoded, 0, data, 2, encoded.length);
        data[data.length - 1] = 0x00;

        final AjpRequestParser.StringHolder holder = newParser().parseString(
                ByteBuffer.wrap(data), state, AjpRequestParser.StringType.URL);

        assertTrue(holder.readComplete);
        assertEquals("/a%20b", holder.value);
        assertTrue(holder.containsUrlCharacters);
        assertFalse(holder.containsUnencodedCharacters);
    }

