    @Test
    public void headersBeyondMaxHeadersAreRejectedAndNotAdded() throws Exception {
        final AjpRequestParser parser = new AjpRequestParser("UTF-8", true, MAX_PARAMETERS, 2, false, false);
        final AjpRequestParseState state = new AjpRequestParseState();
        final HttpServerExchange exchange = new HttpServerExchange(null);

        parser.parse(RequestBuilder.request()
                .codedHeader(0xB, "one")
                .header("X-Two", "two")
                .header("X-Three", "three")
                .buffer(), state, exchange);

        assertTrue(state.isComplete());
        assertTrue(state.badRequest, "too many headers must be flagged as a bad request");
        assertEquals(0, exchange.getRequestHeaders().size(), "headers must be dropped once the limit is exceeded");
    }

    @Test
