        final AjpRequestParser parser = new AjpRequestParser("UTF-8", true, MAX_PARAMETERS, MAX_HEADERS, false, false,
                "allowed\\..*");
        final AjpRequestParseState state = new AjpRequestParseState();
        parser.parse(RequestBuilder.request()
                .requestAttribute("allowed.foo", "bar")
                .requestAttribute("forbidden.foo", "baz")
