    @Test
    public void parse16BitIntegerHandlesSplitReads() {
        final AjpRequestParser parser = newParser();
        final AjpRequestParseState state = new AjpRequestParseState();

        AjpRequestParser.IntegerHolder holder = parser.parse16BitInteger(ByteBuffer.allocate(0), state);
        assertFalse(holder.readComplete);

        holder = parser.parse16BitInteger(ByteBuffer.wrap(new byte[] { 0x12 }), state);
        assertFalse(holder.readComplete);
        assertEquals(-1, holder.value);

        holder = parser.parse16BitInteger(ByteBuffer.wrap(new byte[] { 0x34 }), state);
        assertTrue(holder.readComplete);
        assertEquals(0x1234, holder.value);

        // state has to be reset for the next integer
        holder = parser.parse16BitInteger(ByteBuffer.wrap(new byte[] { 0x00, 0x2A }), state);
        assertTrue(holder.readComplete);
        assertEquals(42, holder.value);
    }

