    @Test
    public void sentinelMethodCodeLeavesRequestMethodUnset() throws Exception {
        final AjpRequestParseState state = new AjpRequestParseState();
        final HttpServerExchange exchange = new HttpServerExchange(null);

    newParser().parse(RequestBuilder.request().method(0xFF).uri("/keep").buffer(), state, exchange);

    assertTrue(state.isComplete());
    assertEquals(HttpString.EMPTY, exchange.getRequestMethod(), "0xFF is the AJP sentinel for an undefined method");
    assertEquals("/keep", exchange.getRequestPath());
}

