        AtomicReference<StreamConnection> upgradedChannel = new AtomicReference<>();
        AtomicReference<HttpServerExchange> upgradedExchange = new AtomicReference<>();
        HttpUpgradeListener upgradeListener = (channel, ex) -> {
            upgradedChannel.set(channel);
            upgradedExchange.set(ex);
