package io.undertow.websockets.core.protocol.version07;

import static org.easymock.EasyMock.createNiceMock;
import static org.easymock.EasyMock.expect;
import static org.easymock.EasyMock.replay;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.HashSet;
import java.util.Set;

import io.undertow.connector.ByteBufferPool;
import io.undertow.server.DefaultByteBufferPool;
import io.undertow.websockets.core.StreamSinkFrameChannel;
import io.undertow.websockets.core.StreamSourceFrameChannel;
import io.undertow.websockets.core.WebSocketChannel;
import io.undertow.websockets.core.WebSocketException;
import io.undertow.websockets.core.WebSocketFrameCorruptedException;
import io.undertow.websockets.core.WebSocketFrameType;
import io.undertow.websockets.core.WebSocketVersion;
import io.undertow.websockets.extensions.ExtensionFunction;
import io.undertow.websockets.extensions.NoopExtensionFunction;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.xnio.OptionMap;
import org.xnio.StreamConnection;
import org.xnio.XnioIoThread;
import org.xnio.channels.Configurable;
import org.xnio.conduits.ConduitStreamSinkChannel;
import org.xnio.conduits.ConduitStreamSourceChannel;
import org.xnio.conduits.EmptyStreamSourceConduit;
import org.xnio.conduits.NullStreamSinkConduit;

/**
 * Tests for the RFC 6455 (WebSocket version 08/13) framing implementation.
 *
 * <p>The transport is represented by XNIO's conduit-backed channels and an EasyMock
 * connection only because constructing an {@link org.xnio.StreamConnection} requires
 * an XNIO provider. No network I/O is performed by these tests.</p>
 */
class WebSocket07ChannelTests {

    private static final String WS_URL = "ws://example.test/socket";
    private static final String SUB_PROTOCOL = "chat";

    private ByteBufferPool bufferPool;
    private StreamConnection connection;

    @BeforeEach
    void setUp() {
        XnioIoThread ioThread = createNiceMock(XnioIoThread.class);
        replay(ioThread);

        ConduitStreamSourceChannel source = new ConduitStreamSourceChannel(
                Configurable.EMPTY, new EmptyStreamSourceConduit(ioThread));
        ConduitStreamSinkChannel sink = new ConduitStreamSinkChannel(
                Configurable.EMPTY, new NullStreamSinkConduit(ioThread));

        connection = createNiceMock(StreamConnection.class);
        expect(connection.getSourceChannel()).andReturn(source).anyTimes();
        expect(connection.getSinkChannel()).andReturn(sink).anyTimes();
        replay(connection);

        bufferPool = new DefaultByteBufferPool(false, 128);
    }

    @AfterEach
    void tearDown() {
        bufferPool.close();
    }

    @Test
    void exposesConfiguredChannelMetadata() {
        WebSocket07Channel channel = newChannel(false, false, NoopExtensionFunction.INSTANCE);

        assertEquals(WebSocketVersion.V08, channel.getVersion());
        assertEquals(WS_URL, channel.getUrl());
        assertEquals(SUB_PROTOCOL, channel.getSubProtocol());
        assertFalse(channel.isClient());
        assertFalse(channel.areExtensionsSupported());
        assertEquals("ws", channel.getRequestScheme());
        assertFalse(channel.isSecure());
        assertSame(NoopExtensionFunction.INSTANCE, channel.getExtensionFunction());
    }

    @Test
    void recognizesSecureWebSocketUrls() {
        WebSocket07Channel channel = newChannel("wss://example.test/secure", true,
                false, NoopExtensionFunction.INSTANCE);

        assertEquals("wss", channel.getRequestScheme());
        assertTrue(channel.isSecure());
        assertTrue(channel.isClient());
    }

    @Test
    void createsConcreteSinkChannelsForEverySupportedFrameType() throws IOException {
        assertSinkChannel(WebSocketFrameType.TEXT, WebSocket07TextFrameSinkChannel.class);
        assertSinkChannel(WebSocketFrameType.BINARY, WebSocket07BinaryFrameSinkChannel.class);
        assertSinkChannel(WebSocketFrameType.PING, WebSocket07PingFrameSinkChannel.class);
        assertSinkChannel(WebSocketFrameType.PONG, WebSocket07PongFrameSinkChannel.class);
        assertSinkChannel(WebSocketFrameType.CLOSE, WebSocket07CloseFrameSinkChannel.class);
    }

    @Test
    void rejectsUnsupportedSinkFrameTypes() {
        WebSocket07Channel continuationChannel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        IllegalArgumentException continuation = assertThrows(IllegalArgumentException.class,
                () -> continuationChannel.send(WebSocketFrameType.CONTINUATION));
        assertTrue(continuation.getMessage().contains("CONTINUATION"),
                () -> "Unexpected message: " + continuation.getMessage());

        WebSocket07Channel unknownChannel = newChannel(true, false, NoopExtensionFunction.INSTANCE);
        IllegalArgumentException unknown = assertThrows(IllegalArgumentException.class,
                () -> unknownChannel.send(WebSocketFrameType.UNKOWN));
        assertTrue(unknown.getMessage().contains("UNKOWN"),
                () -> "Unexpected message: " + unknown.getMessage());
    }

    @Test
    void parsesSingleUnmaskedTextFrameAndLeavesPayloadUntouched() throws IOException {
