 */
class WebSocket07ChannelTests {

    private static final String WS_URL = "ws://example.test/socket";
    private static final String SUB_PROTOCOL = "chat";

    private ByteBufferPool bufferPool;
    private StreamConnection connection;

    @BeforeEach
    void setUp() {
        XnioIoThread ioThread = createNiceMock(XnioIoThread.class);
        replay(ioThread);

        ConduitStreamSourceChannel source = new ConduitStreamSourceChannel(
                Configurable.EMPTY, new EmptyStreamSourceConduit(ioThread));
        ConduitStreamSinkChannel sink = new ConduitStreamSinkChannel(
                Configurable.EMPTY, new NullStreamSinkConduit(ioThread));

        connection = createNiceMock(StreamConnection.class);
        expect(connection.getSourceChannel()).andReturn(source).anyTimes();
        expect(connection.getSinkChannel()).andReturn(sink).anyTimes();
        replay(connection);

        bufferPool = new DefaultByteBufferPool(false, 128);
    }

    @AfterEach
    void tearDown() {
        bufferPool.close();
    }

    @Test
    void exposesConfiguredChannelMetadata() {
        WebSocket07Channel channel = newChannel(false, false, NoopExtensionFunction.INSTANCE);

        assertEquals(WebSocketVersion.V08, channel.getVersion());
        assertEquals(WS_URL, channel.getUrl());
        assertEquals(SUB_PROTOCOL, channel.getSubProtocol());
        assertFalse(channel.isClient());
        assertFalse(channel.areExtensionsSupported());
        assertEquals("ws", channel.getRequestScheme());
        assertFalse(channel.isSecure());
        assertSame(NoopExtensionFunction.INSTANCE, channel.getExtensionFunction());
    }

    @Test
    void recognizesSecureWebSocketUrls() {
        WebSocket07Channel channel = newChannel("wss://example.test/secure", true,
                false, NoopExtensionFunction.INSTANCE);

        assertEquals("wss", channel.getRequestScheme());
        assertTrue(channel.isSecure());
        assertTrue(channel.isClient());
    }

    @Test
    void createsConcreteSinkChannelsForEverySupportedFrameType() throws IOException {
