    @Test
    void textMessageMethodIsBoundAndReceivesMessageLastFlagAndSession() throws Exception {
        AnnotatedEndpointFactory factory = create(TextEndpoint.class);
        TextEndpoint instance = new TextEndpoint();
        AnnotatedEndpoint endpoint = factory.createInstance(handle(instance));

        BoundMethod textMessage = boundMethod(endpoint, "textMessage");
        assertNotNull(textMessage, "a @OnMessage(String) method must be bound as text message handler");
        assertNull(boundMethod(endpoint, "binaryMessage"));
        assertNull(boundMethod(endpoint, "pongMessage"));
        assertEquals(String.class, textMessage.getMessageType());
        assertFalse(textMessage.isDecoderRequired());
        assertTrue(textMessage.hasParameterType(boolean.class));

        Session session = sessionStub();
        textMessage.invoke(instance,
                values(String.class, "hello", boolean.class, Boolean.TRUE, Session.class, session));

        assertEquals(List.of("hello:true"), instance.calls);
        assertSame(session, instance.lastSession);
    }

