    private static AnnotatedEndpointFactory create(final Class<?> endpointClass) throws DeploymentException {
        return AnnotatedEndpointFactory.create(endpointClass, EncodingFactory.DEFAULT, NO_PATHS);
    }

    private static BoundMethod boundMethod(final AnnotatedEndpoint endpoint, final String fieldName) throws Exception {
        Field field = AnnotatedEndpoint.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return (BoundMethod) field.get(endpoint);
    }

    private static Map<Class<?>, Object> values(final Object... keysAndValues) {
        Map<Class<?>, Object> map = new HashMap<>();
        for (int i = 0; i < keysAndValues.length; i += 2) {
            map.put((Class<?>) keysAndValues[i], keysAndValues[i + 1]);
        }
        return map;
    }

    private static <T> InstanceHandle<T> handle(final T instance) {
        return new InstanceHandle<T>() {
            @Override
            public T getInstance() {
                return instance;
            }

            @Override
            public void release() {
            }
        };
    }

    private static <T> InstanceFactory<T> fixedFactory(final T instance) {
        return () -> handle(instance);
    }

    private static Map<Class<?>, List<InstanceFactory<? extends Decoder>>> decoderFactories(final Class<?> type,
                                                                                          final Decoder decoder) {
        InstanceFactory<? extends Decoder> factory = fixedFactory(decoder);
        Map<Class<?>, List<InstanceFactory<? extends Decoder>>> decoders = new HashMap<>();
        decoders.put(type, Collections.singletonList(factory));
        return decoders;
    }

    private static Session sessionStub() {
        return (Session) Proxy.newProxyInstance(AnnotatedEndpointFactoryTests.class.getClassLoader(),
                new Class<?>[] { Session.class }, (proxy, method, args) -> {
                    switch (method.getName()) {
                        case "getPathParameters":
                            return Collections.emptyMap();
                        case "hashCode":
                            return System.identityHashCode(proxy);
                        case "equals":
                            return proxy == args[0];
                        case "toString":
                            return "TestSession";
                        default:
                            break;
                    }
                    Class<?> returnType = method.getReturnType();
                    if (returnType == boolean.class) {
                        return Boolean.FALSE;
                    }
                    if (returnType == long.class) {
                        return 0L;
                    }
                    if (returnType == int.class) {
                        return 0;
                    }
                    return null;
                });
    }

