@Test
void overridingOnMessageInSubclassIsAcceptedAndSubclassMethodIsUsed() throws Exception {
    AnnotatedEndpointFactory factory = create(MessageOverrideEndpoint.class);
    MessageOverrideEndpoint instance = new MessageOverrideEndpoint();
    AnnotatedEndpoint endpoint = factory.createInstance(handle(instance));

    BoundMethod textMessage = boundMethod(endpoint, "textMessage");
    assertNotNull(textMessage);
    textMessage.invoke(instance, values(String.class, "hi"));

    assertEquals(List.of("sub:hi"), instance.calls);
}

@Test
void endpointWithoutAnnotatedMethodsHasNoBoundHandlers() throws Exception {
    AnnotatedEndpointFactory factory = create(PlainEndpoint.class);
    AnnotatedEndpoint endpoint = factory.createInstance(handle(new PlainEndpoint()));

    assertNull(boundMethod(endpoint, "webSocketOpen"));
    assertNull(boundMethod(endpoint, "webSocketClose"));
    assertNull(boundMethod(endpoint, "webSocketError"));
    assertNull(boundMethod(endpoint, "textMessage"));
    assertNull(boundMethod(endpoint, "binaryMessage"));
    assertNull(boundMethod(endpoint, "pongMessage"));
}


@Test
void messageMethodReturnValueIsHandedBackForSending() throws Exception {
    AnnotatedEndpointFactory factory = create(ReturningEndpoint.class);
    ReturningEndpoint instance = new ReturningEndpoint();
    AnnotatedEndpoint endpoint = factory.createInstance(handle(instance));

    BoundMethod textMessage = boundMethod(endpoint, "textMessage");
    assertNotNull(textMessage);
    assertEquals(String.class, textMessage.getMessageType());

    Object result = textMessage.invoke(instance, values(String.class, "hi"));

    assertEquals("HI", result);
}


